잠든 용의 수를 장부에 적고 있다. 그 용들이 언제부터 잠들었는지는 같은 장부에서 찾을 수 있을까."]],["실바렌의 인장",90,7,["party_dmg",100,1.5,1,"실바렌의 맞잡은 힘","「실바렌 공터에서는 씨족 이름을 묻기 전에 짐부터 내려놔. 같이 들어야 멀리 간다.」"]]],[["참나무 균열봉",46,1],["느릅나무 무색홀",48,1],["자작나무 지팡이",45,1],["뿌연 공명구",47,1],["수정 공허봉",49,1],["물푸레나무 균열봉",46,1],["가시나무 무색홀",48,1],["놋쇠 지팡이",45,1],["유리 공명구",47,1],["구리 공허봉",49,1],["물푸레 균열봉",46,1],["단풍나무 무색홀",48,1],["가죽 감은 지팡이",45,1],["고른 공명구",47,1],["놋쇠테 공허봉",49,1],["구리테 균열봉",46,1],["가죽 감은 무색홀",48,1],["매끈한 지팡이",45,1],["맑은 공명구",47,1],["잿빛 공허봉",49,1],["연보라 균열봉",46,1],["달무늬 무색홀",48,1],["깃털무늬 지팡이",45,1],["구름무늬 공명구",47,1],["은가시 공허봉",49,1],["불꽃무늬 균열봉",46,1],["오래 간직한 무색홀",48,2],["고갯길을 건넌 지팡이",45,2],["잿더미에서 건진 공명구",47,2],["잃었다가 찾은 공허봉",49,2],["눈보라를 견딘 균열봉",46,2],["카델의 무색홀",48,9,["abyss_res",100,7,1,"카델의 마른 심연","카델 분소의 검문을 피해 돌아다니던 무색홀이다. 인장 서약을 거부한 마도사에게는 다리 하나 건너는 일이 국경 넘기만큼 멀었다."]],["아샤크의 지팡이",45,9,["chain",100,18,1,"아샤크의 잇따른 타격","「흑요 신전선에서는 불이 길을 밝힌다. 어둠을 찾는 거라면 해자 건너편을 봐라.」"]],["오렐린의 공명구",47,9,["echo",24,33,1,"오렐린의 남은 힘","오렐린 의회는 루미엘 탈환을 국시로 정했다. 다만 길드와는 손잡지 않고 독자 조사단을 따로 보내기로 했다."]],["갈색 자수 로브",75,0],["단단한 비단 두건",72,0],["검은 마도 조끼",79,0],["갈색 어깨옷",76,0],["손질한 주문 장갑",73,0],["묵직한 로브",70,0],["얇은 수놓은 장화",77,0],["헐거운 망토",74,0],["검은 학자 외투",71,0],["오래된 긴 외투",78,0],["깔끔한 자수 로브",75,0],["물들인 비단 두건",72,0],["줄무늬 마도 조끼",79,0],["새로 기운 어깨옷",76,0],["정교한 주문 장갑",73,0],["잘 맞는 로브",70,0],["짙푸른 수놓은 장화",77,0],["반듯한 망토",74,0],["촘촘한 학자 외투",71,0],["물비늘 긴 외투",78,0],["금실 자수 로브",75,0],["이끼빛 비단 두건",72,0],["새벽빛 마도 조끼",79,0],["유리빛 어깨옷",76,0],["은자수 주문 장갑",73,0],["다시 찾은 로브",70,0],["성벽에서 돌아온 장화",77,0],["그을음이 남은 망토",74,0],["오래 간직한 외투",71,0],["옛길에서 찾은 외투",78,0],["베르크홀트의 로브",75,9,["last_stand",100,24,3,"베르크홀트의 마지막 저항","세 차례 대원정을 겪은 베르크홀트는 그 뒤로 철수로를 계약에 적어 넣었다. 다음 원정에서는 그 길이 정말 열려 있을까."]],["프리엔의 두건",72,9,["thorns_shd",100,6,1,"프리엔의 되돌린 충격","프리엔의 불탄 시험실에서 건져 낸 두건이다. 학술원은 화재라고만 적었고, 제적된 이들은 시료를 떠올렸다."]],["알트의 조끼",79,9,["last_stand",100,25,3,"알트의 남은 걸음","「알트 계곡에서는 약속을 쇳조각으로 남긴다. 다 지키지 못할 것 같으면 돌아올 길부터 그려 둬라.」"]],["수선한 문장",87,0],["해진 은팔찌",94,0],["흐린 금반지",81,0],["작은 푸른 보석",88,0],["두꺼운 수정 펜던트",95,0],["평범한 수정 반지",82,0],["투명한 붉은 보석",89,0],["투박한 허리 장식",96,0],["가벼운 목걸이",83,0],["쓰던 인장",90,0],["푸른빛 호박 귀걸이",97,0],["고운 은목걸이",84,0],["붉은빛 브로치",91,0],["비취빛 유리 구슬",98,0],["푸른빛 부적",85,0],["튼튼한 손목띠",92,0],["정련한 별무늬 반지",99,0],["자줏빛 귀걸이",86,0],["저녁빛 펜던트",93,1],["가는 은반지",80,1],["새벽별 문장",87,2],["잿빛 은팔찌",94,2],["촘촘한 금반지",81,2],["은방울 푸른 보석",88,2],["물결무늬 수정 펜던트",95,2],["잿더미에서 건진 반지",82,0],["첫눈을 맞은 보석",89,3],["강을 건너온 장식",96,4],["서둘러 건져낸 목걸이",83,3],["불길에서 건진 인장",90,4],["타이겐의 귀걸이",97,9,["abyss_res",100,10,1,"타이겐의 마른 심연","타이겐 관청 기록은 성 안을 부족 구역, 성 밖을 인간 상인 구역으로 나눈다. 같은 성벽 아래에서도 장부는 둘로 갈렸다."]],["세레디아의 은목걸이",84,9,["echo",25,37,1,"세레디아의 되찾은 숨","두 후계자 중 누가 정당했는지 가릴 문서는 루미엘과 함께 사라졌다. 세레디아라는 이름은 둘 중 누구의 것이었을까."]],["메르벤의 브로치",91,8,["party_dmg",100,2.4,1,"메르벤의 맞잡은 힘","메르벤 관청은 세레디아식 서류는 그대로 쓰는데 성주만 수인으로 바뀌었다. 두 통치가 맞닿은 자리에는 통역이 필요했다."]]]],"la":[[0,20,20,"불굴의 은반지",83,4,"wa_wall",[5,3],"철벽 함성","「나를 보라고 외쳐라. 적의 눈이 이쪽으로 쏠리면 뒤에 선 사람들이 숨을 돌린다.」",13.4],[0,30,30,"상흔의 루비 인장",86,6,"wa_scar",[35,50],"되갚는 상처","케른의 쇠 맹세를 지키는 사람에게는 상처를 셀 틈이 없다. 끝까지 서 있는 쪽이 빚을 갚아 준다.",21.1],[0,40,35,"마지막 성벽의 문장",89,8,"wa_last",[40,2,30],"마지막 성벽","고립의 해, 변경 병사들은 북쪽과 심연 사이에서 눈을 돌릴 겨를이 없었다. 한 사람이 쓰러져도 성벽의 그 자리는 비울 수 없었다.",23.8],[5,20,20,"겹방패 펜던트",92,4,"pa_layer",[25],"겹친 방패","「방패 하나가 가리는 건 한 사람이다. 어깨를 맞대면 그 뒤에 선 사람까지 가려진다.」",13.4],[5,30,30,"부서진 은총 귀걸이",95,6,"pa_echo",[47],"은총의 반향","「보호막이 깨지는 소리가 들리거든 손부터 뻗어라. 새 방패를 세우는 건 다친 사람을 붙잡은 다음이다.」",21.1],[5,40,35,"서광의 맹세 반지",98,8,"pa_wrath",[30,25],"수호자의 분노","「지킬 사람이 남아 있는 동안은 검을 거둘 때가 아니다. 방패 뒤에 숨으라는 말도 입에 올리지 마라.」",23.8],[6,20,20,"만인의 축복 성표",81,4,"pr_bless",[68],"넓은 축복","「기도가 앞줄에서 끊기면 뒷줄은 누가 돌보겠나. 이름 모르는 사람까지 빠짐없이 불러 줘라.」",13.5],[6,30,30,"새벽을 지키는 목걸이",84,6,"pr_miracle",[80,43],"두 번째 기적","등불지기는 죽은 사람의 이름을 부른다. 이 사제는 아직 대답할 수 있는 사람의 이름을 한 번 더 불렀다.",21.2],[6,40,35,"질풍의 기도 브로치",87,8,"pr_swift",[12],"신속의 기도","「내 기도가 끝나기를 기다리지 마라. 내가 손을 들면 먼저 움직여, 뒤는 내가 막는다.」",23.9],[7,20,20,"초록 진액 약병",90,4,"al_brew",[65],"진한 약","「약 아끼다 사람을 잃으면 병 바닥에 한 방울 남은들 무슨 소용이야. 필요한 만큼 따라 줘.」",13.5],[7,30,30,"넘치는 수정 팔찌",93,6,"al_surge",[50,4],"넘치는 생기","넘친 약이 다음 상처를 막아 준다면 낭비가 아니다. 연금술사는 병 바닥까지 알뜰히 쓰는 법부터 배운다.",18.3],[7,40,35,"번진 약병 부적",96,8,"al_splash",[40],"번지는 약병","「병을 던질 자리를 잘 골라라. 튄 약이 어디까지 닿는지는 병 바닥을 본 사람이 제일 먼저 안다.」",23.9],[1,20,20,"쌍그림자 은반지",99,4,"as_shadow",[37],"그림자 연타","「첫 칼로 눈길을 끌어. 다음 칼은 그림자가 놓을 테니, 상대가 돌아설 때면 이미 늦었지.」",13.3],[1,30,30,"검은 바늘 반지",82,6,"as_vital",[48],"급소 노리기","두꺼운 갑옷에도 이음새는 있다. 칼을 더 세게 쥐기보다 그 작은 틈을 오래 들여다보라는 오래된 가르침이다.",21.0],[1,40,35,"추격 월장석 귀걸이",85,8,"as_hunt",[2,85],"사냥꾼의 흐름","「하나 쓰러뜨렸다고 멈추지 마. 다음 발자국이 지워지기 전에 몸부터 돌려.」",23.7],[2,20,20,"풍향 사파이어 귀걸이",88,4,"ar_wind",[10,75],"바람 읽기","「시위를 놓기 전엔 바람이 몇 번 바뀌어도 괜찮다. 놓는 그 순간만큼은 바람이 한 방향이어야 해.」",13.3],[2,30,30,"망루의 매눈 브로치",91,6,"ar_high",[16],"높은 자리","하르벤의 망루는 심연 쪽을 내려다본다. 먼 곳을 먼저 알아본 사수는 한 발을 고를 시간을 번다.",21.0],[2,40,35,"순환 화살 반지",94,8,"ar_chain",[5,100],"연쇄 사격","「맞혔으면 곧장 다음 화살을 꺼내. 맞히고 나서 숨 돌리면 남은 적에게 차례를 내주는 거야.」",23.7],[3,20,20,"영창 방벽 문장",97,4,"sa_ward",[40,95],"방벽 영창","인장 서약은 마법사의 손에 허가와 감시를 한꺼번에 쥐여 주었다. 그래도 긴 영창을 견디는 일은 여전히 각자의 몫이었다.",13.3],[3,30,30,"응축 마력의 반지",80,6,"sa_comp",[42],"압축 마력","「힘을 넓게 펼치면 벽이 흔들리는 데서 끝난다. 한 점에 모으면 돌도 쪼개지니, 쏟아낼 때를 기다려.」",21.0],[3,40,35,"시간 굴절 펜던트",83,8,"sa_warp",[20,50,55],"시간 왜곡","프리엔 학술원은 어디까지 연구해도 되는지를 두고 둘로 갈렸다. 주문 하나를 더 익히는 데도 허가와 두려움이 따라붙었다.",23.7],[4,20,20,"침독 흑요석 부적",86,4,"un_seep",[36],"스며드는 독","「첫 방울은 눈에 띄지도 않아. 걷어 낼 때를 놓쳤구나 싶을 즈음엔 다음 방울이 벌써 스며 있지.」",13.5],[4,30,30,"피값의 마나석",89,6,"un_blood",[3,38,3],"피의 대가","허가받지 않은 주문이라도 대가는 치러야 한다. 고통이 오래갈수록 시전자는 더 오래 손을 뻗는다.",21.2],[4,40,35,"연쇄 파열 보석",92,8,"un_chain",[3,66],"연쇄 폭발","「한 줄씩 지워질 때는 참을 만하지. 겹쳐 있던 줄이 한꺼번에 사라지면 숨도 못 쉰다.」",23.9],[8,20,20,"갈증의 구리 팔찌",95,4,"gl_boil",[83],"끓는 피","「처음부터 피를 흘릴 필요는 없어. 끝나고도 제 발로 걸어 나와서 다음 싸움에 칼을 쥐고 있어야지.」",13.3],[8,30,30,"굶주림의 핏빛 보석",98,6,"gl_hunger",[50,51,10],"굶주린 칼","마렌토의 투기장은 빚을 갚는 곳이면서 구경거리이기도 했다. 몰릴수록 칼을 놓지 못하는 사람이 있었다.",21.0],[8,40,35,"투기왕의 월계 문장",81,8,"gl_king",[15,18,3],"투기장의 왕","티카는 투기장에서 빚을 갚고 자유를 샀다. 이긴 값이 환호인지 자유인지는 관중석에서 정할 수 없다.",23.7],[9,20,20,"심층 균열석 부적",84,4,"ch_rift",[30,31],"깊은 균열","「균열은 겉에서 재면 얕아 보여. 손을 뻗어 봐야 어디까지 이어지는지 알지.」",13.5],[9,30,30,"공허 흡수 목걸이",87,6,"ch_void",[30,21],"공허 흡수","심연을 다루는 사람들은 바닥난 적에게서도 남은 기운을 찾아낸다. 빈 그릇을 들여다보는 눈은 쉴 줄 모른다.",21.2],[9,40,35,"공명의 검은 고리",90,8,"ch_full",[7.5,1.5],"완전한 공명","「고갈된 뒤에도 파동은 멎지 않는다. 속이 빈 곳은 작은 떨림도 멀리까지 울려.」",21.5]]}]==]
