B.SHOP_RAW = [==[{"level_scroll":{"price":1200},"gear":{"rarities":["common","fine"],"stock_per_slot":2,"buy_multiplier":8},"process":{"_d":"장비 가공(대장간 뽑기). 기준 = 출전 가능 캐릭터(페르소나와 영입한 동료) 최고 레벨. 구간마다 가격(금화)과 등급별 확률(가중치 합 100). 등급 착용 레벨(일반1·고급8·희귀15·영웅25·전설32)을 넘는 등급은 그 구간에 없다. 가격은 그 구간 대던전 원정 1회 금화(Lv3 250 · Lv15 420 · Lv25 1,900 · Lv35 3,100)의 약 1/3.","bands":[{"from":1,"to":10,"price":90,"w":{"common":80,"fine":20}},{"from":11,"to":20,"price":140,"w":{"common":55,"fine":35,"rare":10}},{"from":21,"to":30,"price":640,"w":{"common":35,"fine":38,"rare":20,"epic":7}},{"from":31,"to":40,"price":1000,"w":{"common":35,"fine":35,"rare":22,"epic":7.5,"legend":0.5}}]}}]==]

