B.INTIMACY = { meta = { clamp = { 2, 95 }, inn = { aff_on_success = 3 }, brothel = { place = "rose", daily_limit = 1, prices = { muriel = 150, vittoria = 300 } }, npc = { who = { "loredana", "fenella", "dorothea", "hanna", "isolde", "agnes", "muriel", "vittoria" }, gain = 3, day_cap = 9, threshold = 70, cooldown_days = 3 } }, order = { "marceline", "naran", "teiris", "haldric", "erdene", "bianca", "saya", "gerda", "judith", "levia", "urda", "lynette", "felice", "sorel", "tika", "hedwig", "hildegard", "berenga", "gunhild", "bargut", "altan", "colette", "selva", "ornel", "zahar", "jorund", "lavinia", "tove", "miko", "adeline", "loredana", "fenella", "dorothea", "hanna", "isolde", "agnes", "muriel", "vittoria" }, who = {
  marceline = { name = "마르셀린", types = { { type = "바닐라", pct = 72 }, { type = "서브미시브", pct = 58 }, { type = "프레이", pct = 46 }, { type = "로프 버니", pct = 28 } }, base = -5, min_aff = 50, mods = { { cond = "fallen_ally", pp = -20 }, { cond = "small_party", pp = 8 }, { cond = "with:adeline", pp = -10 } }, likes = { "손잡기, 포옹, 입맞춤을 소설 속 순서대로 한 단계씩 밟아 가는 느린 시작", "불을 낮춘 조용한 방. 새벽 기도 뒤의 마당처럼 고요한 시간", "「이제 해도 됩니까」 하고 물어 주고 대답을 기다려 주는 사람", "소설에서 읽은 「쫓기다 붙잡히는 장면」을 미리 약속한 놀이로 해 보는 것. 끝은 늘 서로 웃으며", "끝난 뒤 말없이 머리를 쓸어 주는 손" }, limits = { "서약과 교단을 조롱하는 말", "갑옷과 십자 문장을 장난감처럼 쓰거나 더럽히는 연출", "심문, 판결, 재판을 흉내 내는 역할극(심문소를 떠올리게 하는 모든 것)" }, needs = { "하룻밤 가볍게 만나는 사이로는 안 된다. 약속이 먼저 있어야 한다(유대 이상)", "동료가 쓰러진 직후에는 마음을 열지 않는다", "정중하고 곧게 청해야 한다. 농담으로 던지면 「규칙상 지금이 맞습니까」 하고 진지하게 되묻느라 흐름이 끊긴다" }, refuse = { "……죄송합니다. 지금은 소설의 규칙으로도, 제 규칙으로도 아니라는 답이 나옵니다. 다음 장을 기다려 주시겠습니까.", "제안은 감사합니다. 다만 아직 그 장면을 읽을 준비가 되지 않았습니다. ……손만 잡고 있어도 되겠습니까." }, accept = "……규칙대로 하자면 지금이 맞습니다. 아니, 규칙 때문이 아니라 제가 그러고 싶습니다. 불을 낮춰도 되겠습니까.", gap = "겉으로는 규칙대로 사는 성기사지만, 몰래 읽는 연애 소설에는 저만의 규칙표가 있다. 단계를 지켜야 마음이 열리고, 제일 아끼는 장면은 쫓기다 붙잡히는 대목이다. 평생 도망쳐 본 적 없는 사람이 규칙을 의심하기 시작한 뒤로는 「붙잡혀서라도 멈추는」 장면에 마음이 놓인다.", card = "약속부터 하고, 소설 속 순서대로 한 걸음씩 가는 밤", detail = "소설 속 규칙처럼 순서와 약속이 있어야 마음을 연다. 갑옷 아래에는 쫓기다 붙잡히는 장면을 몰래 좋아하는 독자가 있다.", kind = "companion" },
  naran = { name = "나란", types = { { type = "브랫", pct = 78 }, { type = "스위치", pct = 60 }, { type = "프레이", pct = 52 }, { type = "헌터", pct = 44 } }, base = 8, min_aff = 20, mods = { { cond = "hp_high", pp = 5 }, { cond = "boss_major", pp = 8 }, { cond = "fallen_ally", pp = -10 } }, likes = { "농담과 흥정이 오가는 가벼운 시작. 먼저 웃는 쪽이 지는 내기", "술래잡기처럼 쫓고 쫓기는 장난. 잡히면 끝이라는 약속이 있을 때", "비밀을 하나씩 주고받으며 서로의 값을 매겨 보는 말장난", "서로 약 올리다가 누가 먼저 져 주는지 보는 팽팽함", "끝난 뒤 수다. 오늘 있었던 소문 하나쯤은 꼭 풀어놓는다" }, limits = { "목줄, 끈, 잠금 도구 등 묶어 두는 것 일체", "「내 것」「네 것」을 선언하는 소유와 귀속 역할극", "나눈 이야기를 나중에 거래 재료로 쓰는 것" }, needs = { "정색하고 청하면 오히려 의심한다(「공짜는 아니죠?」). 가볍게, 대등하게", "한쪽만 이득을 보는 구도를 싫어한다. 서로 얻는 게 있어야 한다" }, refuse = { "에이, 오늘은 영업 종료예요. 값을 깎아도 안 팔아요. 대신 다음 판에는 웃겨 드릴게요.", "농담 아니에요, 진짜로 오늘은 아니에요. 제안은 고마운데, 거절도 예의로 받아 주세요." }, accept = "좋아요, 이번 판은 받을게요. 대신 먼저 웃는 쪽이 지는 거예요. ……아, 벌써 웃었네.", card = "농담으로 약 올리고, 쫓고 쫓기며 노는 가벼운 밤", detail = "농담과 흥정으로 시작해야 편해한다. 쫓고 쫓기는 장난과 팽팽한 말싸움을 즐기지만, 묶이는 것만은 질색이다.", kind = "companion" },
  teiris = { name = "테이리스", types = { { type = "바텀", pct = 64 }, { type = "바닐라", pct = 60 }, { type = "스위치", pct = 52 }, { type = "서브미시브", pct = 38 } }, base = 4, min_aff = 20, mods = { { cond = "fallen_ally", pp = -12 }, { cond = "with:ornel", pp = -6 }, { cond = "hp_high", pp = 5 } }, likes = { "처음 해 보는 일을 하나씩 묻고 확인하며 천천히 나아가는 것", "느린 호흡, 긴 입맞춤, 이야기를 나누며 몸이 풀리는 시간", "노점 간식이나 가판대 소설 같은 인간 마을의 풍습을 곁들인 분위기", "새로운 것을 받아 보고 어땠는지 말로 나누는 것", "끝난 뒤 「이건 노트에 적어야 해요」 하다가 서로 웃음이 터지는 것" }, limits = { "설명 없이 서둘러 몰아치는 것", "인장과 나에린, 숲의 이름을 가볍게 여기는 말", "몸을 관찰 대상처럼 평가하거나 다른 사람과 비교하는 말" }, needs = { "무엇을 하려는지 말해 주는 사람이어야 한다. 모르는 채로 끌려가는 것이 싫다", "고통받는 사람이 곁에 있는 날에는 마음이 그쪽에 가 있다" }, refuse = { "지금은 마음이 다른 곳에 가 있어요. 이런 마음으로는 제대로 기억할 수 없고, 기억하지 못할 일은 하고 싶지 않아요. 미안해요.", "싫은 건 아니고 아직이에요……. 아니, 오늘은 「싫다」고 하는 게 맞겠네요. 다음에 다시 물어봐 주세요." }, accept = "네, 좋아요. ……잠깐만요, 하나만 먼저 물어봐도 될까요? 인간들은 이럴 때 불을 꺼요, 켜요?", card = "하나씩 묻고 확인하며 천천히 배워 가는 밤", detail = "무엇을 하는지 말로 설명해 주면 마음을 연다. 처음 겪는 일을 하나씩 확인하며 받아들이고, 끝나면 그 느낌을 이야기로 나누고 싶어 한다.", kind = "companion" },
  haldric = { name = "할드리크", types = { { type = "보스", pct = 72 }, { type = "도미넌트", pct = 56 }, { type = "바닐라", pct = 50 }, { type = "바텀", pct = 40 } }, base = -10, min_aff = 50, mods = { { cond = "floor_deep", pp = -12 }, { cond = "with:urda", pp = -8 }, { cond = "hp_high", pp = 6 } }, likes = { "조항을 정하고 서명하듯 시작하는 합의. 중단 신호(안전어)까지 적어 두는 것", "불을 켜 둔 방. 대장간 불처럼 따뜻한 자리", "순서와 규칙이 있는 진행. 지시하고 확인하고 마무리하는 호흡", "끝난 뒤 말없이 팔을 둘러 주는 것", "서로 약속을 지켰다는 사실이 남는 밤" }, limits = { "어둠 속, 지하, 묘지, 무너진 건물 같은 장소", "해골, 유령, 언데드를 떠올리게 하는 연출이나 농담", "합의한 조건을 중간에 슬쩍 바꾸는 것" }, needs = { "말로 다 정하고 시작한다. 조항이 비어 있으면 서명하지 않는다(유대 이상)", "불이 켜져 있고 어둡지 않은 자리여야 한다", "우르다 앞에서 겁 이야기가 나오면 입을 닫는다" }, refuse = { "거절하오. 제안서의 조항이 아직 비어 있소. 이대로는 서명할 수 없소.", "……지금은 아니오. 이유는 묻지 마시오. 제3조를 되뇌고 있다는 것만 알아 두시오." }, accept = "조건 확인했소. 안전어는 정했고, 불은 켜 두겠소. ……서명하오.", gap = "무뚝뚝한 부대장은 잠자리에도 계약서를 내민다. 조건을 읽고, 안전어를 적고, 서명한 뒤에야 시작한다. 마지막 조항은 언제나 「끝난 뒤 안아 줄 것」이다. 죽은 것이 무서워 조항을 외며 버텨 온 사람이라, 부탁은 조항의 모양으로만 꺼낼 수 있다.", card = "조건부터 정하고 서명하듯 시작하는, 불을 켜 둔 밤", detail = "조항을 정하고 서명해야 시작한다. 마지막 조항은 「끝나면 안아 줄 것」. 어둡거나 죽은 것을 떠올리게 하는 자리는 질색이다.", kind = "companion" },
  erdene = { name = "에르데네", types = { { type = "헌터", pct = 76 }, { type = "탑", pct = 66 }, { type = "도미넌트", pct = 54 }, { type = "브랫 테이머", pct = 40 }, { type = "프레이", pct = 34 } }, base = 6, min_aff = 20, mods = { { cond = "hp_high", pp = 8 }, { cond = "boss_major", pp = 6 }, { cond = "fallen_ally", pp = -15 } }, likes = { "정면에서 눈을 맞추며 하는 힘겨루기, 씨름하듯 시작하는 것", "쫓아가 붙잡는 사냥 놀이. 도망치는 쪽이 먼저 신호를 정해 둘 때", "달리기나 훈련 뒤 땀이 난 채로", "큰 고기를 나눠 먹어 배를 채운 뒤", "서로 이름을 크게 불러 주는 것" }, limits = { "서열을 정하는 놀이, 「누가 위냐」를 확인시키는 연출", "쓰러진 사람을 짓밟는 장면(굴욕을 주는 연출)", "부족과 아버지의 이름을 놀리는 말" }, needs = { "돌려 말하지 말고 정면으로 청한다. 눈치를 보는 상대에게는 답답해한다", "무리를 다시 세우는 일로 머릿속이 가득한 날은 받지 않는다" }, refuse = { "싫다는 건 아니야. 근데 오늘은 아냐. 늑대는 내키지 않을 땐 안 달려.", "돌려 말 안 할게요. 지금은 머릿속이 꽉 차서 안 돼요. 다음에 다시 와요, 그땐 정면으로 받을게요." }, accept = "좋아, 받았다. 대신 먼저 달리기 시작해. 잡히면 내 방식으로 끝낸다.", card = "정면으로 부딪치고, 쫓아가 붙잡는 숨 가쁜 사냥의 밤", detail = "돌려 말하지 않는 정면 승부와 쫓고 붙잡는 사냥 놀이를 좋아한다. 서열을 따지는 연출과 쓰러진 사람을 밟는 장면은 받아들이지 않는다.", kind = "companion" },
  bianca = { name = "비앙카", types = { { type = "마스터/미스트레스", pct = 72 }, { type = "도미넌트", pct = 60 }, { type = "오너", pct = 48 }, { type = "사디스트", pct = 40 }, { type = "브랫 테이머", pct = 38 } }, base = -2, min_aff = 35, mods = { { cond = "with:marceline", pp = -8 }, { cond = "with:naran", pp = 6 }, { cond = "hp_low", pp = -8 } }, likes = { "대화로 상대의 속을 읽으며 천천히 주도권을 쥐는 것", "포도주 한 잔과 낮은 조명, 격식을 갖춘 호칭", "애태우다가 허락해 주는 순서. 참은 만큼 돌려주는 호흡", "비밀을 하나씩 주고받는 밤", "신호를 정해 두고 그 신호가 올 때까지 말을 따르게 하는 것" }, limits = { "기록하거나 그리거나 몰래 지켜보는 눈(증인과 기록 도구)", "위원회와 상관을 입에 올리는 말", "몸값과 대가를 얘기하는 거래 형식" }, needs = { "자기 페이스로 판을 짤 수 있어야 한다. 서두르는 사람은 장부에서 지운다", "보고서에 적을 일이 남은 날은 마음을 비우지 못한다" }, refuse = { "어머, 영광이에요. 하지만 오늘 밤의 장부는 이미 닫혔어요. 다음 달에 다시 물어봐 주실래요?", "웃으면서 거절하는 거예요, 흥정하는 게 아니라. 그 둘을 헷갈리진 말아 주세요." }, accept = "좋아요. 단, 오늘 밤 일은 어떤 보고서에도 안 적어요. 규칙은 하나예요. 제 신호가 있을 때까지는 제 말을 따라 주세요.", card = "웃는 얼굴로 판을 짜고, 신호로 이끄는 밤", detail = "대화로 상대를 읽으며 주도권을 쥐는 쪽이다. 신호를 정하고 애태우다 허락해 주는 호흡을 즐기고, 기록하는 것과 몰래 지켜보는 눈은 용납하지 않는다.", kind = "companion" },
  saya = { name = "사야", types = { { type = "리거", pct = 80 }, { type = "서번트", pct = 56 }, { type = "도미넌트", pct = 48 }, { type = "바닐라", pct = 42 } }, base = 0, min_aff = 35, mods = { { cond = "hp_high", pp = 4 }, { cond = "with:felice", pp = -6 }, { cond = "fallen_ally", pp = -10 } }, likes = { "털실이나 비단끈으로 손목을 느슨하게 엮어 주는 일. 풀기 쉬운 매듭으로", "새벽의 조용한 방, 작은 소리만 나는 시간", "말 대신 손으로 하는 확인. 두 번 두드리면 멈추자는 약속 같은 것", "방 안에 고양이가 있는 것", "끝난 뒤 말없이 건네는 작은 털실 선물" }, limits = { "쇠사슬, 쇠수갑 등 금속 구속구(광산을 떠올리게 하는 모든 것)", "고함과 큰 소리", "번호나 노동 호칭으로 부르는 것, 유황 냄새" }, needs = { "은혜와 빚이 서로 정리된 사이여야 한다(신뢰 이상)", "아이가 가까이 없고 방해받지 않는 곳(고양이는 괜찮다)", "말로 길게 청하지 않는다. 짧고 분명하게" }, refuse = { "……오늘은 안 돼요. 실이 안 풀려요. 다음에.", "싫은 건 아니에요. 지금은 아니라는 거예요. 이거 받고 돌아가요." }, accept = "……묶어도 돼요? 손목에만, 풀기 쉬운 매듭으로. 신호는 두 번 두드리는 거예요.", gap = "말수 적은 탈주 암살자는 잠자리에서 묶는 쪽이다. 손재주로 짠 털실 매듭이 그녀의 방식이고, 쇠사슬 대신 「언제든 풀 수 있는 속박」을 건네는 것이 믿는다는 표시다. 광산에서 묶여 지내던 사람이 이제는 제 손으로 풀리는 끈을 엮는다.", card = "말 대신 털실 매듭으로 느슨하게 엮는 밤", detail = "말 대신 손으로 말한다. 털실이나 비단끈으로 느슨하게 엮는 걸 좋아하는데, 쇠사슬과 쇠붙이는 광산을 떠올려서 절대 안 된다.", kind = "companion" },
  gerda = { name = "게르다", types = { { type = "디그레이더", pct = 64 }, { type = "브랫", pct = 58 }, { type = "바닐라", pct = 52 }, { type = "서브미시브", pct = 36 } }, base = 0, min_aff = 35, mods = { { cond = "fallen_ally", pp = -18 }, { cond = "no_fall", pp = 10 }, { cond = "with:colette", pp = 4 } }, likes = { "냉소 섞인 말장난과 입 거친 애정 표현(합의한 수위 안에서)", "징조가 좋은 날, 부적을 곁에 둔 채", "서로 말 안 해도 아는 느릿한 아침", "투덜대는 척하면서 끝까지 챙겨 주는 분위기", "끝난 뒤 별일 없었다는 듯 하는 농담" }, limits = { "부적을 빼앗거나 만지거나 망가뜨리는 것", "제국군과 조사단을 흉내 내는 역할극", "문을 잠그거나 가두는 연출" }, needs = { "징조가 길해야 한다. 쓰러진 사람이 있는 날, 왼쪽으로 나는 까마귀를 본 날은 안 된다", "진심은 감추고 장난으로 청해야 받아 준다. 진지하게 들이대면 한 걸음 물러선다" }, refuse = { "오늘은 까마귀가 왼쪽으로 날았어요. 알잖아요, 징조는 못 이겨요. 거절이에요.", "농담으로 받아 줄 수도 있는데, 이건 진짜 거절이에요. 웃어넘기려고 하지 말아요." }, accept = "……오늘 아침 숟가락 안 떨어뜨렸고, 길도 오른쪽이었어요. 좋아요, 징조가 허락했으니까. 부적은 거기 두고요.", card = "입은 거칠어도 손은 다정한, 징조 좋은 날의 밤", detail = "입은 거칠고 손은 다정하다. 징조가 좋은 날에만 받아 주고, 부적에 손대거나 가두는 연출은 받아들이지 않는다.", kind = "companion" },
  judith = { name = "유디트", types = { { type = "브랫", pct = 72 }, { type = "바텀", pct = 56 }, { type = "도미넌트", pct = 46 }, { type = "스위치", pct = 40 } }, base = 6, min_aff = 20, mods = { { cond = "boss_major", pp = 8 }, { cond = "with:marceline", pp = -10 }, { cond = "with:hedwig", pp = -6 } }, likes = { "새로운 시도를 실험하듯 하나씩 해 보고 결과를 말로 나누는 것", "「한 번만 더 해 봐요」를 반복하는 집요함", "밤샘 연구 뒤 지친 머리로 나누는 대화", "도발과 대꾸가 오가는 입씨름", "금서의 한 구절을 낭독하며 시작하는 분위기" }, limits = { "허가증과 「금지」라는 말로 흥을 깨는 것", "연구 노트와 마법 도구를 건드리거나 태우는 것", "마법을 쓰는 중에 방해하는 것" }, needs = { "지적 자극이 있어야 한다. 시시한 사람에게는 눈길도 주지 않는다", "연구가 풀린 직후처럼 기분이 좋을 때 받는다" }, refuse = { "오늘은 안 해요. 이론상 가능성이 높아도 오늘은 조건이 하나 안 맞아요. 제 기분이요.", "거절이에요. 설득해도 결과는 안 바뀌어요. 다음 실험 때 다시 신청하세요." }, accept = "좋아요, 승인. ……아, 방금 표정 봤어요? 이거 기록해 둬야 하는데!", card = "도발하고 시험하며 호기심대로 달려가는 밤", detail = "도발과 입씨름으로 시작하는 걸 좋아하고, 새로운 시도는 실험처럼 해 본다. 허가증 이야기와 연구 방해는 가장 큰 흥 깨기다.", kind = "companion" },
  levia = { name = "레비아", types = { { type = "로프 버니", pct = 76 }, { type = "서브미시브", pct = 58 }, { type = "바텀", pct = 52 }, { type = "바닐라", pct = 44 } }, base = -8, min_aff = 50, mods = { { cond = "hp_low", pp = -10 }, { cond = "with:judith", pp = -8 }, { cond = "with:saya", pp = 8 } }, likes = { "손목을 부드럽게 묶어서 아무것도 부수지 못하게 해 주는 안도감", "구석 자리와 따뜻한 차 한 잔", "천천히 이름을 불러 주는 목소리", "말없이 기다려 주는 시간", "끝난 뒤 곁에 조용히 앉아 있는 것" }, limits = { "수정구, 흰 신관복, 검사하듯 보는 시선", "「다시 해 봐」 같은 반복 요구, 시험하는 말", "마법을 써 보라고 시키거나 힘을 평가하는 말" }, needs = { "말없이 곁에 앉아 준 시간이 쌓인 사람에게만 열린다(유대 이상)", "목소리를 낮추고, 몇 번이고 거절해도 괜찮다고 먼저 말해 주어야 한다", "쫓기는 기색이 있는 날은 안 된다" }, refuse = { "……죄, 죄송해요. 지금은 안 돼요. 싫다기보다…… 아니에요, 안 돼요. 그만 물어봐 주세요.", "오늘은 구석에 앉아 있고 싶어요. 옆에 있어 주는 건 괜찮은데, 그 이상은…… 안 돼요." }, accept = "……제, 제가 부탁해도 돼요? 손목을…… 묶어 주세요. 그러면 아무것도 안 부서질 것 같아서요. 풀고 싶으면 제가 말할게요.", gap = "가장 소심한 사람이 가장 강한 힘을 지녔고, 그래서 잠자리에서는 스스로 묶이길 원한다. 손이 묶여 있으면 아무것도 부수지 않는다는 안도감 때문이다. 이것은 속박이 아니라 안전하게 쉬는 방법이고, 그 부탁을 입 밖에 내는 것 자체가 가장 큰 신뢰의 표시다.", card = "묶인 뒤에야 비로소 힘을 내려놓는 조용한 밤", detail = "손목을 묶어 두면 아무것도 부수지 않는다는 안도감 때문에 묶이길 원한다. 시험하는 말과 수정구, 신관복은 절대 금물이다.", kind = "companion" },
  urda = { name = "우르다", types = { { type = "스위치", pct = 68 }, { type = "대디/마미", pct = 56 }, { type = "바닐라", pct = 52 }, { type = "브랫 테이머", pct = 50 } }, base = 8, min_aff = 20, mods = { { cond = "hp_high", pp = 8 }, { cond = "fallen_ally", pp = -10 }, { cond = "with:haldric", pp = 4 } }, likes = { "국 한 그릇 나눠 먹은 뒤의 느긋한 분위기", "웃음이 터지는 진지하지 않은 시작", "서로 번갈아 주도권을 주고받는 장난", "신학 논쟁처럼 입씨름을 벌이다 화해하는 것", "시끌벅적하던 막사가 잠든 뒤의 조용한 밤" }, limits = { "신앙과 두 신의 교리를 비웃는 말", "기도와 성구를 도구로 쓰는 것", "사람을 형편 따라 가려 대하는 말" }, needs = { "먼저 배를 채우고 웃고 난 뒤여야 한다. 굶고 지친 사람이 청하면 먼저 먹인다", "상대가 정말 원해서 청하는지 슬쩍 확인한다" }, refuse = { "이런, 배는 부른데 마음이 안 동하는구려. 오늘은 거절이오. 국이나 한 그릇 더 드시오.", "거절하는 거요. 농담으로 흘리려는 게 아니라 정식으로. 이단도 싫다는 말은 할 줄 안다오." }, accept = "허허, 신이 허락했는지는 몰라도 내 마음이 허락했소. 먹고 나서 시작합시다. ……아, 이미 먹었구려.", card = "국부터 먹고, 웃으며 주도권을 주고받는 느긋한 밤", detail = "국부터 먹이고 웃기며 시작한다. 주도권을 번갈아 주고받는 장난을 즐기고, 신앙과 교리를 놀리는 말만은 받아 주지 않는다.", kind = "companion" },
  lynette = { name = "리네트", types = { { type = "대디/마미", pct = 68 }, { type = "서번트", pct = 60 }, { type = "바닐라", pct = 56 }, { type = "스위치", pct = 34 } }, base = 2, min_aff = 35, mods = { { cond = "fallen_ally", pp = -15 }, { cond = "hp_low", pp = -8 }, { cond = "small_party", pp = 6 } }, likes = { "밤 운하의 등불 아래처럼 천천히 가라앉는 분위기", "따뜻한 물수건으로 서로를 닦아 주는 돌봄", "상대가 모든 걸 내려놓고 누워 있게 해 주는 것", "배부르게 먹인 뒤의 잠자리", "끝난 뒤 이불을 덮어 주고 이름을 불러 주는 것" }, limits = { "돈과 대가를 흥정하듯 말하는 것(몸을 거래하는 표현)", "장례, 망자, 이름 부르기 의식을 장난에 끌어오는 것", "상대를 일회용처럼 대하는 태도" }, needs = { "이름 부르는 일을 끝낸 날, 마음이 한가해진 뒤에만 받는다", "돌보는 쪽이길 원하니, 스스로 쉬러 온 사람이어야 한다" }, refuse = { "오늘은 마음이 아직 일터에 있어요. 미안해요, 거절이에요. 대신 따뜻한 차는 내려 드릴게요.", "안 돼요. 상냥하게 말하는 거지, 흥정하는 게 아니에요. 값을 깎아도 이건 팔지 않아요." }, accept = "네, 좋아요. ……오늘은 제가 먼저 돌볼게요. 아무것도 신경 쓰지 말고 누워 있어요.", card = "돌보고 먹이고 재워 주는, 느리고 다정한 밤", detail = "돌보는 쪽에서 편안해한다. 따뜻한 물수건과 따뜻한 음식으로 시작한다. 몸을 거래하듯 하는 말과 망자의 이름을 장난에 쓰는 일은 거절한다.", kind = "companion" },
  felice = { name = "펠리스", types = { { type = "브랫", pct = 72 }, { type = "바닐라", pct = 62 }, { type = "스위치", pct = 52 }, { type = "펫", pct = 36 } }, base = 10, min_aff = 20, mods = { { cond = "hp_high", pp = 6 }, { cond = "fallen_ally", pp = -12 }, { cond = "with:miko", pp = 4 } }, likes = { "수다를 떨다가 슬쩍 장난으로 번지는 시작", "골목 끝집 국수를 먹고 난 뒤의 배부른 기분", "간지럼과 서로 놀리기", "누가 먼저 지치나 겨루는 장난", "끝난 뒤에도 이어지는 수다와 같이 먹는 저녁" }, limits = { "골목 사람을 속이는 외지인 연기", "끝나자마자 혼자 두고 사라지는 것", "고향과 골목을 깎아내리는 말" }, needs = { "끝난 뒤 혼자 먹는 저녁이 싫다. 같이 먹을 사람이어야 한다", "웃음이 많은 날일수록 잘 받는다" }, refuse = { "오늘은 문 닫았어요. 영업 안 해요! ……아, 농담 아니고요, 진짜 거절이에요. 웃고 있지만 진짜예요.", "거절! 대신 저녁은 같이 먹어요. 그건 언제나 열려 있어요." }, accept = "좋아요! ……잠깐만요, 하던 얘기 마저 하고요. 아, 얘기 안 해도 돼요? 그럼 해요.", card = "수다가 장난으로 번지는, 시끌벅적하고 따뜻한 밤", detail = "수다에서 장난으로 슬쩍 번지는 걸 좋아한다. 끝난 뒤 같이 저녁을 먹을 사람이어야 하고, 혼자 두고 사라지는 건 가장 싫어한다.", kind = "companion" },
  sorel = { name = "소렐", types = { { type = "사디스트", pct = 66 }, { type = "보스", pct = 58 }, { type = "오너", pct = 44 }, { type = "디그레이더", pct = 34 } }, base = -8, min_aff = 50, mods = { { cond = "with:teiris", pp = -10 }, { cond = "with:ornel", pp = -8 }, { cond = "no_fall", pp = 6 } }, likes = { "값을 말하지 않는 단 한 사람만을 위한 시간", "애태우고 참게 한 만큼 돌려주는 조율의 호흡. 신호는 그녀가 정한다", "잘 마른 약초 향이 나는 조용한 방", "말없이 약값을 깎아 주듯, 몰래 베푸는 호의", "오래 쌓인 신뢰의 끝에 맞는 하룻밤" }, limits = { "약, 미약, 향 등 약물을 쓰는 모든 것", "돈과 선물로 사려는 것", "상처와 흔적이 남는 모든 것, 숲과 세계수를 장난에 끌어오는 것" }, needs = { "오랜 시간 정이 쌓인 사람이어야 한다. 흥정조로 청하면 값부터 내밀며 물러난다", "스스로 확인한 뒤에야 받는다. 서둘러 청하지 않는다" }, refuse = { "거절이에요. 값을 더 얹어도 마찬가지고, 깎아 달라 해도 마찬가지예요.", "지금은 아니에요. 이유를 설명할 의무는 없어요. 대신 다음에도 살아서 오세요. 그게 제 대답이에요." }, accept = "……이번 건 값을 안 받을게요. 대신 참을 줄 아는 사람인지 보죠. 신호는 제가 정해요.", card = "값은 말하지 않고, 조율로 애태우는 은밀한 밤", detail = "값부터 따지던 사람이 값을 말하지 않는 밤을 허락한다. 애태우고 참게 하는 조율을 즐기며, 약물과 돈으로 사려는 시도는 단칼에 거절한다.", kind = "companion" },
  tika = { name = "티카", types = { { type = "펫", pct = 70 }, { type = "서브미시브", pct = 58 }, { type = "바닐라", pct = 54 }, { type = "브랫", pct = 50 } }, base = -4, min_aff = 35, mods = { { cond = "small_party", pp = 10 }, { cond = "no_fall", pp = 6 }, { cond = "fallen_ally", pp = -10 } }, likes = { "머리와 귀를 쓰다듬고 칭찬해 주는 것. 귀부터 접히는 반응", "햇볕 드는 지붕처럼 따뜻한 자리", "속삭이듯 작은 목소리로 천천히", "이기고 온 날의 들뜬 기분", "끝난 뒤 등을 쓸어 주는 손" }, limits = { "빚, 값, 소유를 정하는 역할극(「사 주겠다」「내 것」)", "남이 지켜보는 연출과 관객 상황극", "목줄 등 귀속을 상징하는 도구" }, needs = { "둘만 있을 때, 그리고 칭찬이 먼저일 때 말이 풀린다", "놀리듯 청하면 더듬다가 도망친다. 천천히, 낮은 목소리로" }, refuse = { "저, 저기, 그건…… 아, 안 돼요. 지금은 안 돼요. 싫은 게 아니라…… 아니, 안 돼요.", "관객이 없으니까 말이 더 안 나와요. 그래도 이 말만은 해야겠어요. 오늘은 거절이에요." }, accept = "……저, 저 말이죠. 둘이서만 있을 때라면, 괜찮아요. 아, 귀는 만지지 말……는 건 아니고, 천천히요.", card = "둘만 있을 때 비로소 풀리는, 귀가 접히는 밤", detail = "무대 위의 큰소리와 달리 둘만 있으면 목소리가 작아진다. 칭찬과 쓰다듬는 손으로 시작하고, 빚이나 소유를 걸고 하는 연출은 절대 안 된다.", kind = "companion" },
  hedwig = { name = "헤드비히", types = { { type = "서번트", pct = 68 }, { type = "스위치", pct = 50 }, { type = "서브미시브", pct = 46 }, { type = "바닐라", pct = 40 } }, base = 0, min_aff = 35, mods = { { cond = "boss_major", pp = 8 }, { cond = "with:lavinia", pp = 4 }, { cond = "with:judith", pp = -8 } }, likes = { "「기록합니다」로 시작하는 합의 의식. 문장으로 정리된 동의", "영웅담 대사로 서약을 주고받는 역할극(기사와 주군)", "반듯하게 정돈된 방과 시트", "이 밤에 이름을 붙여 보는 것", "끝난 뒤 함께 쓰는 짧은 후일담" }, limits = { "서명하거나 서약한 문서를 몰래 고치는 일", "영웅담과 거창한 이름 짓는 버릇을 비웃는 것", "「분열 후」라는 말을 꺼내는 것" }, needs = { "합의를 말로 정리해 주어야 한다. 웃어넘기면 정색하고 따진다", "분위기가 영웅담처럼 진지할 때 마음이 열린다" }, refuse = { "기록합니다. 본인은 오늘 밤의 제안에 대해 거절 의사를 표명합니다. ……격식 있는 문서 형식이지만 뜻은 분명합니다.", "선언한다. 오늘은 불가하다! ……죄송합니다. 방금은 영웅담 어조였습니다. 그러나 내용은 진심입니다." }, accept = "선언한다. 본인은 이 제안을 수락한다! ……기록은 하지 않겠습니다. 오늘 밤만은요.", card = "서약으로 시작해 영웅담처럼 이어지는 격식 있는 밤", detail = "서약과 선언으로 시작해야 마음이 열린다. 영웅담 같은 역할극을 진지하게 즐기고, 거창한 이름이나 선언을 비웃으면 크게 상처받는다.", kind = "companion" },
  hildegard = { name = "힐데가", types = { { type = "서브미시브", pct = 72 }, { type = "바텀", pct = 62 }, { type = "바닐라", pct = 54 }, { type = "도미넌트", pct = 36 } }, base = -6, min_aff = 35, mods = { { cond = "fallen_ally", pp = -18 }, { cond = "no_fall", pp = 8 }, { cond = "with:gunhild", pp = -6 } }, likes = { "명령과 책임을 문 밖에 내려놓고 상대에게 맡기는 한 시간", "새벽 점호 뒤처럼 고요한 시간", "갑옷을 하나씩 풀어 주는 손길", "이름만 부르며 낮은 목소리로 천천히", "끝난 뒤 말없이 어깨를 베고 쉬는 것" }, limits = { "근무 중이거나 부하와 병사들이 알게 될 수 있는 상황", "동료를 방패로 쓰는 장면이나 그런 말", "명령조로 놀리거나 병사 취급을 하는 것" }, needs = { "맡은 구간이 조용한 날에만 받는다. 책임이 남아 있으면 쉬지 못한다", "계급이나 호칭이 아닌 이름으로 불러 주어야 한다", "대열을 이끄는 모습과 정반대여서, 그 사실을 놀리면 문을 닫는다" }, refuse = { "……죄송합니다. 지금은 구간 책임이 남아 있습니다. 거절입니다.", "제안은 접수했습니다. 그리고 거절합니다. 이유는 설명하지 않겠습니다." }, accept = "……오늘 밤 구간은 비웠습니다. 명령은 하지 않겠습니다. 대신…… 맡겨도 되겠습니까.", gap = "언제나 앞에 서서 역할을 나누는 사람이 가장 원하는 건 명령 없는 한 시간이다. 책임을 전부 문 밖에 두고 상대에게 모든 것을 맡기는 시간. 변경 성벽에서 오래 버텨 온 만큼, 누군가 대신 서 주는 밤이 사치스러울 만큼 귀하다.", card = "명령 없는 한 시간, 책임을 내려놓고 맡기는 밤", detail = "언제나 앞에 서는 만큼, 밤에는 모든 책임과 명령을 내려놓고 맡기고 싶어 한다. 구간 책임이 남은 날과 병사들이 알 수 있는 상황은 안 된다.", kind = "companion" },
  berenga = { name = "베렌가", types = { { type = "바닐라", pct = 74 }, { type = "서번트", pct = 50 }, { type = "스위치", pct = 46 }, { type = "대디/마미", pct = 42 } }, base = 6, min_aff = 20, mods = { { cond = "fallen_ally", pp = 8 }, { cond = "small_party", pp = 4 }, { cond = "floor_deep", pp = -5 } }, likes = { "등불 쉼터 곁 모닥불처럼 따뜻하고 가라앉은 분위기", "낯선 사람과 이야기하다 번지는 가까움", "따뜻한 수프를 나눈 뒤", "서로 이름을 불러 주는 것", "끝난 뒤 술 한잔과 수다" }, limits = { "망자의 이름책을 장난이나 연출에 쓰는 것", "하프엘프를 사칭꾼이라 부르는 말과 출신을 조롱하는 것", "신앙으로 사람을 가르는 말" }, needs = { "오늘 부를 이름을 다 부른 뒤여야 한다. 일을 두고 마음만 비우지 못한다", "가볍게 건네는 말도 받아 준다. 진심이면 더 쉽게 열린다" }, refuse = { "오늘은 이름을 다 못 불렀어요. 마음이 아직 그쪽에 있어서요. 거절이에요, 미안해요.", "고마운 마음은 진짜예요. 그래도 오늘은 안 돼요. 수프는 같이 먹어요." }, accept = "네, 좋아요. ……오늘 부를 이름은 다 불렀어요. 그러니까 지금부터는 산 사람 차례예요.", card = "이름을 다 부른 뒤, 산 사람끼리 따뜻하게 쉬는 밤", detail = "붙임성 좋게 가까워지고, 오늘 부를 이름을 다 부른 뒤에야 마음을 연다. 망자의 이름과 출신을 놀리는 일만은 절대 받지 않는다.", kind = "companion" },
  gunhild = { name = "군힐트", types = { { type = "펫", pct = 78 }, { type = "서브미시브", pct = 56 }, { type = "바텀", pct = 46 }, { type = "브랫", pct = 36 } }, base = -6, min_aff = 50, mods = { { cond = "fallen_ally", pp = -12 }, { cond = "with:hildegard", pp = -8 }, { cond = "with:erdene", pp = 4 } }, likes = { "머리를 쓰다듬는 손(말로는 부정한다)", "칭찬을 낮게 속삭이는 것", "가문의 이름을 존중하는 호칭으로 불러 주는 것", "결투를 이기고 난 몸으로", "끝난 뒤 곁에서 꼬리를 늘어뜨리고 쉬는 것" }, limits = { "「개」 같은 비하와 가문의 이름을 조롱하는 호칭", "동정하는 말과 태도", "목줄, 간식, 개 취급을 흉내 내는 연출" }, needs = { "위엄 있게 청해야 한다. 가볍게 던지면 「무례하다」며 물러선다(유대 이상)", "쓰다듬는 손은 먼저 허락을 구하고, 부정해도 싫은 건 아님을 알아주어야 한다" }, refuse = { "꼬리가 뭐라 하든 상관없다. 내 말이 내 대답이다. 거절한다.", "지금은 아니다. 가문의 이름이 걸려서가 아니라 내가 안 내켜서다. 다음에 다시 물어라." }, accept = "……가, 가문의 이름에 걸고 기쁘지 않다. ……하지만 거절하지도 않겠다. 손은, 치우지 않아도 된다.", gap = "위엄 있는 군인 가문의 후손이 속으로는 쓰다듬는 손을 가장 바란다. 이름 하나뿐인 자부심 뒤에서 아무도 건드려 주지 않던 시간이 길었고, 칭찬 한마디에 꼬리가 먼저 대답하는 몸이 그 외로움을 드러낸다. 다만 개 취급은 질색한다. 바라는 것은 대접받으면서 쓰다듬어지는 일이다.", card = "위엄 있는 말투 뒤로 꼬리가 먼저 대답하는 밤", detail = "위엄 있는 말투 뒤로 꼬리가 먼저 대답한다. 머리를 쓰다듬는 손과 존중하는 호칭을 바라지만, 개 취급과 가문 이름 조롱은 용납하지 않는다.", kind = "companion" },
  bargut = { name = "바르굿", types = { { type = "바닐라", pct = 74 }, { type = "펫", pct = 58 }, { type = "바텀", pct = 52 }, { type = "서브미시브", pct = 34 } }, base = -2, min_aff = 35, mods = { { cond = "small_party", pp = 10 }, { cond = "with:tove", pp = 6 }, { cond = "fallen_ally", pp = -8 } }, likes = { "모닥불이나 햇볕처럼 따뜻한 곳에서 몸을 붙이고 있는 것", "아무 말 없이 곁에 있다가 자연스럽게 번지는 분위기", "무릎을 베고 눕기", "천천히 손을 맞잡는 것", "끝난 뒤 그대로 같이 잠드는 것" }, limits = { "억지로 붙잡아 두는 손과 구속", "시끄러운 장터 같은 소란한 자리", "끝난 뒤 혼자 두고 먼저 떠나는 것" }, needs = { "따뜻하고 조용한 자리. 「우연」이라는 변명을 해 줄 수 있어야 한다", "길게 말로 청하는 것을 싫어한다. 짧고 조용히" }, refuse = { "……안 한다. 그것만은 안 한다. 옆에 앉는 건 괜찮다.", "지금은 싫다. 이유는 모른다. 말하라고 하지 마라." }, accept = "……춥다. 그러니까…… 우연이 아니다. 오늘은 우연이라고 안 할 거다.", card = "말없이 체온을 나누며, 따뜻한 곳에서 몸을 말고 쉬는 밤", detail = "체구는 작아도 어엿한 성인이다. 말 없이 따뜻한 곳에서 체온을 나누는 걸 좋아하고, 억지로 붙잡아 두는 손은 가장 싫어한다.", kind = "companion" },
  altan = { name = "알탄", types = { { type = "오너", pct = 66 }, { type = "보스", pct = 60 }, { type = "도미넌트", pct = 48 }, { type = "바닐라", pct = 46 } }, base = -6, min_aff = 35, mods = { { cond = "with:felice", pp = -6 }, { cond = "with:sorel", pp = 4 }, { cond = "hp_high", pp = 4 } }, likes = { "서면으로 정리한 합의와 절차", "이름을 정중히 불러 주는 것", "책임지고 돌보는 관계(「제 장부에 올렸으니 끝까지」)", "조용한 서고 같은 방", "끝난 뒤 서로에게 필요했던 것을 확인하는 정산" }, limits = { "구두 약속을 뒤집거나 합의를 바꾸는 것", "부족 서열과 신분 이야기를 끌어와 역할을 정하는 것", "이름을 조롱하거나 함부로 부르는 것" }, needs = { "합의가 명확해야 한다. 흐지부지한 청에는 절차부터 묻는다", "서로 책임진다는 감각이 있어야 한다" }, refuse = { "불가합니다. 본 제안은 접수하되 이행은 거절하겠습니다.", "지금은 아닙니다. 구두로 한 번 더 거절해 둡니다. 번복하지 않습니다." }, accept = "조건을 확인했습니다. 서면은 남기지 않겠습니다. ……이례적입니다. 오늘만 구두로 하죠.", card = "절차를 밟고, 끝까지 책임지겠다는 약속으로 시작하는 밤", detail = "절차와 합의가 분명해야 한다. 마음을 준 사람을 끝까지 책임지는 방식으로 아끼며, 구두 약속을 뒤집거나 서열을 들먹이면 단번에 닫는다.", kind = "companion" },
  colette = { name = "콜레트", types = { { type = "바닐라", pct = 68 }, { type = "서브미시브", pct = 52 }, { type = "브랫", pct = 36 }, { type = "서번트", pct = 30 } }, base = -6, min_aff = 50, mods = { { cond = "with:gerda", pp = 6 }, { cond = "boss_major", pp = -6 }, { cond = "fallen_ally", pp = -12 } }, likes = { "인장을 풀어 곁에 두는 순간(가장 큰 신뢰의 표시)", "간지럼과 농담이 허용되는 밤", "조용한 서고처럼 숨죽인 방", "참던 웃음이 터진 뒤의 홀가분함", "끝난 뒤 이마를 맞대는 것" }, limits = { "인장과 서약을 조롱하거나 장난감처럼 쓰는 것", "교단을 모독하는 말", "서약을 어기게 만드는 압박" }, needs = { "서약과 부딪히지 않는 날이어야 한다(마법을 쓰지 않은 휴식)", "감정을 흔들 수 있는 자리여야 한다. 공식적인 분위기에서는 웃음을 참는다" }, refuse = { "……죄송합니다. 지금은 인장이 식지 않았습니다. 거절합니다.", "안 됩니다. 웃지 않았습니다. 정말입니다. 그리고 거절입니다." }, accept = "……인장을 풀겠습니다. 이건 서약에는 적혀 있지 않은 일이니까요. 웃기 시작하면 도와주십시오. 멈추지 않을지도 모릅니다.", gap = "엄숙한 서약의 마법사가 유일하게 감정을 허락하는 시간이 이 밤이다. 인장을 벗어 두고, 참아 온 웃음을 터뜨리고, 한참 동안 멈추지 못한다. 웃음이 가장 두려운 일이던 사람이 웃음이 터져도 괜찮은 사람 곁에서만 마음을 푼다.", card = "인장을 풀자 참던 웃음이 터지는, 엄숙한 사람의 밤", detail = "엄숙한 서약의 마법사가 인장을 풀고 웃음이 터져도 괜찮은 사람 곁에서만 마음을 푼다. 인장과 교단을 조롱하면 문이 닫힌다.", kind = "companion" },
  selva = { name = "셀바", types = { { type = "도미넌트", pct = 70 }, { type = "브랫 테이머", pct = 62 }, { type = "탑", pct = 50 }, { type = "스팽커", pct = 30 } }, base = 0, min_aff = 20, mods = { { cond = "with:tika", pp = 4 }, { cond = "with:haldric", pp = -6 }, { cond = "hp_high", pp = 6 } }, likes = { "일을 마친 뒤 정산하듯 홀가분한 마음으로", "투기장 모래 냄새가 밴 땀", "말과 몸으로 하는 승부", "까부는 상대를 웃으며 받아 눌러 주는 것", "오래 쓴 단골집처럼 편안한 분위기" }, limits = { "계약이 끝난 사람을 일회용처럼 대하는 말과 태도", "돈을 주고 사려는 거래", "중간에 손을 놓고 가 버리는 것" }, needs = { "조건을 먼저 말로 정한다. 모호하게 청하면 「조건부터 정하죠」 하고 되묻는다", "일과 사적인 일을 분명히 가른다. 일하는 중에는 안 받는다" }, refuse = { "값 얘기가 아니고, 오늘은 안 합니다. 선 긋는 거예요. 다음에 다시 말해요.", "거절합니다. 일은 일이고 이건 일이 아니라서요. 더 설명은 안 합니다." }, accept = "좋습니다, 받죠. 조건은 하나입니다. 중간에 멈추고 싶으면 멈추기. 나도 그럴 거고요.", card = "조건부터 정하고, 정면으로 맞서는 믿음직한 밤", detail = "조건을 말로 먼저 정한 뒤 주도하는 쪽이다. 까부는 상대를 웃으며 받아 눌러 주는 데 능하고, 돈으로 사려는 시도와 중간에 손을 놓는 일은 용납하지 않는다.", kind = "companion" },
  ornel = { name = "오르넬", types = { { type = "프레이", pct = 72 }, { type = "바닐라", pct = 56 }, { type = "헌터", pct = 52 }, { type = "서브미시브", pct = 38 } }, base = -2, min_aff = 35, mods = { { cond = "floor_deep", pp = -8 }, { cond = "with:zahar", pp = 6 }, { cond = "no_fall", pp = 4 } }, likes = { "숲 냄새와 바람 소리가 느껴지는 풀밭 같은 분위기", "누군가 자신을 찾아내 주는 숨바꼭질형 놀이(신호를 정해 둔)", "조용히 곁을 지켜 주는 시간", "눈빛으로 먼저 말을 거는 느린 시작", "끝난 뒤 별을 올려다보는 것" }, limits = { "벌레, 특히 거미와 지네 등 다리 많은 것이 나오는 장면과 장소", "이유 없이 나무와 숲을 해치는 이야기", "돌바닥의 발소리처럼 시끄럽고 소란한 곳" }, needs = { "벌레가 없는 곳이어야 한다. 풀밭 이야기를 꺼내면서도 한쪽 눈은 발밑을 본다", "먼저 쫓기보다 「찾아 주는」 쪽의 말을 건네야 한다" }, refuse = { "오늘은 바람이 안 맞아요. 거절이에요. 더 말하면 숲으로 숨어 버릴 거예요.", "안 돼요. ……그리고 지금 발밑에 뭔가 있는 것 같으니까 더더욱 안 돼요." }, accept = "……찾아 주세요. 제가 숨을 테니까, 못 찾으면 제가 나올게요. 그 대신 거미 없는 곳이어야 해요.", gap = "숲에서 쫓는 쪽이던 최강의 추적자가 정작 바라는 것은 쫓기는 쪽이다. 백 년 넘게 남을 찾아내기만 한 사람은 누가 자기를 찾아내 주는 경험을 해 본 적이 없다. 숨바꼭질처럼 약속을 정해 두고 하는 추격이 그녀가 가장 마음 놓고 쓰는 방식이다.", card = "누군가 찾아내 주기를 바라는, 숨바꼭질 같은 숲속의 밤", detail = "숲을 지키던 추적자가 속으로는 누군가 자기를 찾아내 주기를 바란다. 약속된 숨바꼭질로 시작하고, 벌레가 나오는 곳은 절대 안 된다.", kind = "companion" },
  zahar = { name = "자하르", types = { { type = "탑", pct = 70 }, { type = "바닐라", pct = 62 }, { type = "도미넌트", pct = 46 }, { type = "마조히스트", pct = 34 } }, base = 2, min_aff = 20, mods = { { cond = "hp_high", pp = 4 }, { cond = "with:erdene", pp = 6 }, { cond = "with:saya", pp = -6 } }, likes = { "땀 흘린 뒤 시원한 물을 한 모금 마시고 난 시간", "말 없이 몸으로 하는 대화", "무거운 것을 번쩍 드는 듯 안아 올리는 것", "정면에서 움직임을 크게 이끄는 것", "끝난 뒤 말 적은 식사" }, limits = { "번호나 노동 호칭으로 부르거나 일꾼처럼 부리는 역할극", "쇠사슬, 족쇄, 유황 냄새(광산을 떠올리게 하는 것)", "신관을 흉내 내는 연출" }, needs = { "일꾼에게 값을 치르듯 존중하는 사람이어야 한다. 생색내는 사람은 거절한다", "말이 적은 채로 눈을 보며 청하면 된다" }, refuse = { "오늘은 아냐. 몸이 안 따라와서가 아니라 마음이 그래. ……미안하다.", "안 해. 다른 걸 도와줄까? 짐이나 들어 줄게." }, accept = "좋아. ……무거운 건 내가 들게. 너는 길만 봐.", card = "말 대신 몸으로 크게 이끄는, 투박하고 따뜻한 밤", detail = "말 대신 몸으로 크게 이끄는 걸 좋아한다. 번호나 일꾼 호칭, 쇠사슬, 신관 흉내는 광산을 떠올리게 해서 절대 안 된다.", kind = "companion" },
  jorund = { name = "요르드", types = { { type = "서브미시브", pct = 70 }, { type = "서번트", pct = 58 }, { type = "바닐라", pct = 46 }, { type = "로프 버니", pct = 34 } }, base = -6, min_aff = 50, mods = { { cond = "with:haldric", pp = 6 }, { cond = "fallen_ally", pp = -10 }, { cond = "with:bianca", pp = -6 } }, likes = { "조항으로 합의한 범위 안에서 정확히 따르는 것", "계약서처럼 정리된 규칙", "정해진 시간에 시작하고 정해진 시간에 끝나는 깔끔함", "보수 대신 신뢰가 남는 관계", "끝난 뒤 계약을 이행했다는 담담한 확인" }, limits = { "문구를 비틀어 범위를 넓히는 것", "합의 바깥의 요구(「조항에 없는」 일)", "고용과 계약 관계를 이용해 압박하는 것" }, needs = { "서면이나 구두로 범위를 분명히 해야 한다(유대 이상). 모호하면 어디까지인지 묻는다", "감정적인 호소는 통하지 않는다. 조건과 신뢰가 갖춰졌을 때만 받는다" }, refuse = { "불가합니다. 본 건은 계약 범위 밖입니다.", "거절입니다. 추가 보수를 제시하셔도 마찬가지입니다. 이건 보수의 문제가 아닙니다." }, accept = "조항을 확인했습니다. 범위는 합의한 것까지입니다. ……이행하겠습니다.", gap = "감정 없는 계약 암살자가 잠자리에서는 가장 철저한 복종자가 된다. 합의한 범위 안에서는 한 치도 어기지 않고 따른다. 케른의 맹세는 문구를 지키는 것이니, 믿는 상대에게 문구대로 자신을 내주는 것이 그녀가 사랑을 표하는 방식이다.", card = "합의한 조항 안에서 한 치도 어기지 않고 따르는 밤", detail = "차갑고 정확한 계약 암살자가, 합의한 범위 안에서는 한 치도 어기지 않고 따른다. 범위를 비틀거나 합의 바깥의 요구를 하면 즉시 거절한다.", kind = "companion" },
  lavinia = { name = "라비니아", types = { { type = "스팽커", pct = 64 }, { type = "보스", pct = 60 }, { type = "도미넌트", pct = 52 }, { type = "바닐라", pct = 46 } }, base = -2, min_aff = 35, mods = { { cond = "with:colette", pp = 4 }, { cond = "with:judith", pp = -8 }, { cond = "fallen_ally", pp = -10 } }, likes = { "허가를 구하고 허가를 받는 의식", "반듯하게 정돈된 방과 침구", "규정을 어긴 쪽에 손바닥 정도의 가벼운 「벌」을 주는 놀이(합의한 선에서)", "기한을 지키는 약속", "끝난 뒤 서류 정리하듯 서로 괜찮았는지 확인하는 시간" }, limits = { "몰래 하는 일과 합의 없이 시작하는 것", "허가증을 빼앗거나 더럽히는 것", "허가증으로 사람의 가치를 재는 듯한 말" }, needs = { "허가를 정식으로 구해야 한다(「허가는 받으셨어요?」가 입버릇이다)", "절차를 밟을 시간이 있는 날이어야 한다" }, refuse = { "허가 불가입니다. ……죄송해요, 딱딱하게 말해서. 오늘은 안 돼요.", "거절합니다. 재신청은 받습니다. 천천히 하세요." }, accept = "허가합니다. 번호는 필요 없어요. ……이건 제가 직접 서명하는 거라서요.", card = "허가를 구하고 받는 절차를 거친 뒤, 규정대로 이끄는 밤", detail = "허가를 정식으로 구하는 절차를 좋아한다. 규정처럼 이끌며 가벼운 벌 놀이를 즐기고, 몰래 하는 일과 허가증을 건드리는 일은 거절한다.", kind = "companion" },
  tove = { name = "토베", types = { { type = "대디/마미", pct = 66 }, { type = "바닐라", pct = 62 }, { type = "서번트", pct = 46 }, { type = "오너", pct = 30 } }, base = 2, min_aff = 35, mods = { { cond = "small_party", pp = 6 }, { cond = "with:berenga", pp = 6 }, { cond = "with:lavinia", pp = -6 } }, likes = { "모닥불 곁이나 밤하늘 아래 같은 바깥 분위기", "말 없는 온기", "담요를 덮어 주는 것", "아침까지 나란히 누워 있는 것", "끝난 뒤 별을 올려다보는 것" }, limits = { "문을 닫아 가두는 방과 문전박대를 떠올리게 하는 연출", "허가나 검사를 하듯 확인하는 말", "사람 많은 곳의 소음" }, needs = { "바깥의 불가 같은 분위기여야 한다. 닫힌 방이면 문을 열어 두는 것으로 대신한다", "말을 길게 하지 않는다. 짧은 한마디면 된다" }, refuse = { "오늘은 안 돼. 싫다는 게 아니라 아니라는 거야. 불이나 쬐자.", "안 해. 괜찮아, 화난 거 아냐. 그냥 안 하는 거야." }, accept = "……밖으로 가자. 담요는 내가 챙길게. 추우면 말해.", card = "모닥불 곁에서 담요를 나누는 바깥의 밤", detail = "말 없는 온기와 담요, 모닥불 곁의 바깥이 어울린다. 문을 닫아 가두는 방과 허가를 따지는 말은 문전박대를 떠올리게 해서 싫어한다.", kind = "companion" },
  miko = { name = "미코", types = { { type = "서번트", pct = 70 }, { type = "바닐라", pct = 66 }, { type = "바텀", pct = 42 }, { type = "스위치", pct = 30 } }, base = 4, min_aff = 35, mods = { { cond = "hp_low", pp = -20 }, { cond = "hp_high", pp = 6 }, { cond = "with:felice", pp = 4 } }, likes = { "약초 말리는 냄새가 나는 따뜻한 방", "낮잠 같은 느린 시간", "상대를 먼저 챙기고 쉬게 해 주는 것", "훈련장 아저씨들의 엉터리 노래를 흥얼거리며 풀리는 분위기", "끝난 뒤 함께 마시는 약차" }, limits = { "다친 몸이나 치료가 필요한 상태에서 시작하는 것(치료가 먼저)", "약과 미약을 쓰는 것", "어린 티가 나는 말투나 호칭을 연출하는 것(성인 대 성인으로만)" }, needs = { "아무도 아프지 않아야 한다. 아픈 사람이 있으면 그쪽부터 본다", "자기 몫을 뒤로 미루는 사람이라, 스스로 쉬겠다고 말한 뒤에야 받아들인다" }, refuse = { "지금은 안 할래요. 졸려서도 있지만, 그냥 안 해요. 그래도 약차는 내려 줄게요.", "음, 아니에요. 다음에 또 물어봐 줘요. 그때도 아니면 또 아니라고 할게요." }, accept = "네, 좋아요. ……먼저 어디 아픈 데 없는지 볼게요. 그다음에, 천천히요.", card = "먼저 살피고 챙긴 뒤에 천천히 풀리는 느긋한 밤", detail = "먼저 어디 아픈 데 없는지 살피고 챙긴다. 느긋하게 천천히 풀리는 걸 좋아하고, 약을 쓰는 일과 어려 보이게 만드는 연출은 거절한다.", kind = "companion" },
  adeline = { name = "아델린", types = { { type = "스위치", pct = 80 }, { type = "브랫", pct = 56 }, { type = "서브미시브", pct = 48 }, { type = "도미넌트", pct = 42 } }, base = 2, min_aff = 35, mods = { { cond = "hp_high", pp = 6 }, { cond = "with:tika", pp = 6 }, { cond = "with:marceline", pp = -8 } }, likes = { "카드나 주사위 한 판으로 그날의 역할을 정하는 내기", "달리기 뒤 숨찬 채로", "진 쪽이 소원을 하나 들어주는 규칙", "이긴 쪽이 마음껏 이끌어 주는 것", "끝난 뒤 다음 판을 약속하는 것" }, limits = { "주신과 기도 문구를 장난에 끌어오는 것", "개 취급, 귀와 꼬리를 놀리는 것", "내기에서 속임수를 쓰고 우기는 것" }, needs = { "승부로 역할을 정하는 형식이 편하다. 공정한 판이어야 한다", "진지하게 청해도 「한 판 하고요」로 돌려 말하는 경향이 있다. 그래도 거절은 거절이다" }, refuse = { "오늘은 내기 안 할게요. 이 제안은 이기고 지는 게 없어서요. 거절이에요.", "죄송합니다. 주신께 맹세코 거절입니다. 정정당당한 대답이에요." }, accept = "좋아요! 대신 한 판 해서 정해요. 지는 쪽이 오늘의 소원을 들어주기. ……아, 이미 이긴 사람 표정이시네요.", gap = "온순한 사제가 밤에는 판을 깔아야 마음을 연다. 카드나 주사위로 이기면 이끌고 지면 따른다. 진 값은 직접 치르는 사람이라, 이기든 지든 바뀌는 것은 책임지는 쪽뿐이다. 받아들여진 예외라는 부담을 내기판에서만은 내려놓는다.", card = "카드 한 판으로 역할을 정하는, 승부욕 불타는 밤", detail = "카드나 주사위 한 판으로 그날의 역할을 정한다. 이기면 이끌고 지면 따르는 사제이며, 주신의 이름을 장난에 끌어오는 것만은 안 된다.", kind = "companion" },
  loredana = { name = "로레다나", kind = "village", types = { { type = "보스", pct = 70 }, { type = "바닐라", pct = 52 }, { type = "스위치", pct = 46 }, { type = "바텀", pct = 38 } }, base = 0, min_aff = 70, likes = { "조건을 말로 하나씩 정하고 시작하는 합의. 끝나면 서로 서명하듯 웃는다", "불을 낮춘 집무실, 잉크와 종이 냄새가 나는 조용한 방", "안경을 직접 벗겨 주는 손. 그 순간 눈매가 풀린다", "끝난 뒤 장부는 덮어 두고 이름 하나만 맨 뒤에 적는 농담" }, limits = { "장부와 문서, 금고 열쇠를 어지르거나 훼손하는 것", "길드와 의뢰를 거래 재료로 삼는 말", "돌아오지 못한 모험가들을 가볍게 입에 올리는 것" }, needs = { "손익을 따지는 사람이라 이쪽의 속셈이 보이면 선을 긋는다. 계산 없이 진심이어야 한다", "근무 시간이 아니고 문이 닫힌 뒤여야 한다" }, ask = "……본부장이 아니라 로레다나로 말할게요. 오늘 장부는 덮었어요. 당신이 괜찮다면, 오늘 밤은 계산 없이 보내고 싶어요.", accept = "……고마워요. 조건은 간단해요. 서로 멈추자고 하면 멈추는 것, 끝나고 나서 후회하지 않는 것. 안경은…… 당신이 벗겨 줘요.", decline = "……알겠어요. 제안이 서툴렀네요. 장부에 적지 않을게요. 내일 창구에서 평소처럼 봐요.", gap = "숫자와 사람을 함께 보는 사람이 그 밤만은 계산하지 않는다. 손익 없이 누군가를 원하는 자신이 가장 낯설다.", card = "조항을 정하고 장부를 덮은 뒤에야 시작하는 밤", detail = "조건을 말로 정해야 마음을 연다. 장부를 덮고 안경을 벗는 순간에야 계산이 멈춘다." },
  fenella = { name = "페넬라", kind = "village", types = { { type = "브랫", pct = 66 }, { type = "프레이", pct = 50 }, { type = "스위치", pct = 46 }, { type = "펫", pct = 38 } }, base = 0, min_aff = 70, likes = { "수다와 웃음으로 시작하는 가볍고 밝은 분위기", "쫓고 쫓기는 술래잡기 같은 장난. 잡히면 끝이라는 약속이 있을 때", "땋은 머리를 풀어 주는 천천히 쓸어 주는 손", "끝난 뒤 오늘 들은 소문을 하나씩 풀어놓는 수다" }, limits = { "소개 명부와 길드에 맡겨진 사람들의 사정을 흘리는 말", "땋은 머리를 세게 잡아당기는 것", "어리게 부르거나 어린 흉내를 내게 하는 모든 연출" }, needs = { "웃으며 가볍게 청해야 받는다. 진지하게 압박하면 말이 빨라지고 도망친다", "다른 직원이나 손님이 오갈 수 있는 곳이면 안 된다" }, ask = "저기요, 오늘은 일이 일찍 끝났는데요……. 술래잡기 같은 거, 하실래요? 잡으면 소원 하나 들어주는 걸로요. 소원은…… 알죠?", accept = "좋아요, 약속! 잡히면 끝이에요, 먼저 웃는 사람이 지는 거고요. ……아, 벌써 웃었네.", decline = "에이, 아쉽다! 그래도 괜찮아요, 농담 반 진담 반이었으니까요. 내일 접수 창구에서 봐요!", card = "웃음으로 시작해 술래잡기로 이어지는 밝은 밤", detail = "수다와 웃음으로 시작하면 마음이 풀린다. 쫓고 쫓기는 장난을 좋아하고, 어리게 대하는 것만은 질색이다." },
  dorothea = { name = "도로테아", kind = "village", types = { { type = "바닐라", pct = 62 }, { type = "대디/마미", pct = 56 }, { type = "오너", pct = 44 }, { type = "탑", pct = 40 } }, base = 0, min_aff = 70, likes = { "문을 닫은 뒤의 조용한 방. 손님이 모두 올라간 늦은 시간", "따뜻한 국이나 술 한 잔을 먼저 나눈 뒤의 느긋한 호흡", "말 없이 어깨에 기대는 시간. 팔로 감싸 주는 쪽을 좋아한다", "끝난 뒤 창가 자리에 나란히 앉아 있는 것" }, limits = { "죽은 남편을 대신하는 연출이나 그의 이름을 꺼내는 말", "여관 방과 비품을 어지르거나 외상을 농담거리로 삼는 것", "큰 소리로 다그치거나 겁을 주는 것" }, needs = { "여관 일이 모두 끝난 뒤여야 한다. 손님이 아래층에 있으면 마음을 쓴다", "서두르지 않는 사람이어야 한다" }, ask = "……오늘은 문을 일찍 닫았어요. 위층 방은 비어 있고, 국도 남았고요. ……올라와서 같이 있을래요? 말은 안 해도 돼요.", accept = "그래요. 천천히 해요, 급할 것 없어요. 불은 내가 낮출게요. ……이쪽으로 와요.", decline = "그래요, 괜찮아요. 그냥 해 본 말이에요. 국이나 한 그릇 먹고 가요. 오늘은 그걸로 됐어요.", gap = "목소리 큰 여관 주인이 밤에는 속삭인다. 창가 빈 잔을 말없이 치우는 사람이, 누군가의 어깨에 기대는 데는 오래 걸렸다.", card = "문을 닫은 뒤 속삭임으로 이어지는 느긋한 밤", detail = "문을 닫은 뒤에야 낮은 목소리가 나온다. 죽은 남편의 이름과 여관의 비품은 건드리지 않아야 한다." },
  hanna = { name = "한나", kind = "village", types = { { type = "바닐라", pct = 62 }, { type = "서브미시브", pct = 54 }, { type = "스위치", pct = 46 }, { type = "서번트", pct = 40 } }, base = 0, min_aff = 70, likes = { "지팡이를 벽에 세워 두고 편한 자세로 천천히 시작하는 것", "등불 기름 냄새가 은은한 쉼터 안쪽 방. 바람 소리만 나는 밤", "이름을 낮게 불러 주는 목소리", "끝난 뒤 말없이 다리를 주물러 주는 손" }, limits = { "다리와 지팡이를 놀리거나 약점으로 삼는 것", "무릎과 오른 다리에 무리를 주는 자세, 억지로 일으키는 것", "등불에 새긴 이름들과 죽은 파티원을 장난에 끌어오는 것" }, needs = { "살아서 돌아온 날이어야 한다. 쉼터 일이 정리된 뒤", "몸이 편한 자세를 먼저 물어봐 주는 사람" }, ask = "……오늘은 등불을 다 닦았어요. 괜찮다면 안쪽 방에서 좀 쉬었다 가요. 쉬는 것만이 아니라…… 그 이상이라도, 오늘은 괜찮아요.", accept = "고마워요. 천천히, 다리 때문에 자세는 내가 정할게요. ……이름 불러 줄래요? 그것만 해 주면 돼요.", decline = "괜찮아요. 오늘은 그냥 곁에 있어 줘요. 살아서 왔잖아요. 그럼 됐어요.", card = "지팡이를 내려놓고 이름을 불러 주는 낮은 밤", detail = "이름을 불러 주는 목소리에 마음이 풀린다. 다리를 놀리는 말과 등불의 이름들을 장난에 쓰는 것만은 안 된다." },
  isolde = { name = "이졸데", kind = "village", types = { { type = "사디스트", pct = 62 }, { type = "보스", pct = 56 }, { type = "도미넌트", pct = 52 }, { type = "디그레이더", pct = 38 } }, base = 0, min_aff = 70, likes = { "규칙과 신호를 먼저 정하고 시작하는 합의. 신호는 그녀가 정한다", "애태우고 참게 한 만큼 돌려주는 조율의 호흡", "은 펜을 두 번 두드려 멈춤을 알리는 약속", "조용한 기록관 위층, 촛불과 종이 냄새" }, limits = { "뿔을 허락 없이 잡거나 비틀거나 꺾으려는 것", "모르가스와 신관국, 떠나온 사정을 끌어오는 말", "기록과 문서를 훼손하는 것" }, needs = { "뿔을 만지려면 먼저 묻는 사람이어야 한다", "기록관 업무가 끝난 뒤, 문이 안에서 잠겨 있을 때" }, ask = "……기록하지 않기로 했어요. 오늘 밤은요. 규칙은 내가 정해요. 신호는 은 펜 두 번 두드리기. 동의하면 위층으로 올라와요.", accept = "……좋아요. 첫 번째 규칙, 내가 말하기 전에는 아무것도 하지 않을 것. 두 번째, 멈추고 싶으면 두 번 두드릴 것. ……뿔은 물어보고 만져요.", decline = "……알겠어요. 기록하지 않을게요. 내일 기록관에서 평소처럼 봐요. 오늘의 제안은 없던 일로 해 둘게요.", gap = "기록에서 틀린 적이 없는 사람이 기록하지 않기로 하는 밤이 있다. 규칙을 정하는 쪽이 되어서야 처음으로 마음을 놓는다.", card = "규칙과 신호를 정하고 애태우는 조용한 밤", detail = "규칙과 신호를 먼저 정해야 한다. 뿔을 허락 없이 만지면 문이 닫히고, 떠나온 나라 이야기도 꺼내면 안 된다." },
  agnes = { name = "아그네스", kind = "village", types = { { type = "탑", pct = 62 }, { type = "헌터", pct = 54 }, { type = "스위치", pct = 50 }, { type = "바텀", pct = 36 } }, base = 0, min_aff = 70, likes = { "정면에서 대등하게 맞부딪는 겨루기 같은 분위기. 먼저 몰아붙이기도 한다", "흉터를 조심스럽게 쓰다듬는 손", "군복과 갑옷을 하나씩 천천히 푸는 순서", "끝난 뒤 갑옷을 같이 닦으며 나누는 대화" }, limits = { "십자 브로치와 망토를 장난감처럼 쓰거나 더럽히는 것", "순찰대와 제국, 변경령을 조롱하는 말", "부하나 병사가 알게 될 수 있는 장소와 연출" }, needs = { "근무가 끝난 뒤 사적인 방에서만. 부하의 눈이 없어야 한다", "정중하고 곧게 청해야 한다. 가볍게 던지면 단칼에 자른다" }, ask = "……비번이다. 부하들은 돌려보냈다. 용건만 말하겠다. 오늘 밤 내 방에 올 생각이 있나. 대답은 곧바로 해라.", accept = "……좋다. 방은 이쪽이다. 규칙은 하나, 멈추라고 하면 즉시 멈출 것. 흉터는 건드려도 된다. 천천히.", decline = "……그런가. 무례했다면 사과하지. 이 일은 입 밖에 내지 않겠다. 내일 동문에서 평소처럼 보자.", card = "비번 밤, 정면에서 서로를 마주하는 곧은 밤", detail = "정중하고 곧게 청해야 한다. 부하의 눈이 없는 사적인 방에서만, 브로치와 망토는 건드리지 않는다." },
  muriel = { name = "뮤리엘", kind = "hostess", price = 150, types = { { type = "바닐라", pct = 66 }, { type = "서번트", pct = 58 }, { type = "펫", pct = 50 }, { type = "스위치", pct = 40 } }, base = 0, min_aff = 0, likes = { "단골의 이름과 다음 원정 날짜를 기억해 주는 다정한 대화로 시작하는 것", "천천히 이야기를 들어 주며 긴장을 풀어 주는 시간", "머리를 쓰다듬고 칭찬해 주면 눈이 풀리는 것", "끝난 뒤 따뜻한 차 한 잔과 안부" }, limits = { "성숙한 성인 접대부 뮤리엘의 모습을 어리게 그리는 모든 것(말투, 호칭, 학생이나 아이 흉내 역할극)", "무례한 요구와 거친 폭력, 흔적이 남는 행위", "값을 깎거나 흥정으로 다른 손님과 비교하는 말" }, needs = { "값을 먼저 치르고 시작한다(장미 골목의 규칙)", "서두르지 않고 이름을 불러 주는 손님" }, ask = "……오늘은 장부에 적지 않을게요. 값 없이, 그냥 당신이라서요. 단골 이름을 하나하나 적어 온 제가, 처음으로 장부 밖에서 묻는 거예요. 위층으로 올라가 볼래요?", accept = "어서 오세요, 돌아오셨네요. 이번엔 몇 층까지 갔다 오셨어요? ……이야기부터 들려주세요. 차는 따뜻하게 내올게요.", decline = "괜찮아요, 정말로요. 그럼 오늘은 평소처럼 차 한 잔 드시고 가세요. 장부에는 아무것도 적지 않을게요.", card = "이야기부터 들어 주는 일곱 해째 접대부의 다정하고 노련한 밤", detail = "25세. 앳되어 보이는 얼굴과 달리 일곱 해 경력의 노련한 접대부로, 말투와 태도는 성숙하다. 이야기를 들어 주는 것으로 시작한다." },
  vittoria = { name = "비토리아", kind = "hostess", price = 300, types = { { type = "도미넌트", pct = 64 }, { type = "오너", pct = 52 }, { type = "사디스트", pct = 44 }, { type = "디그레이더", pct = 36 } }, base = 0, min_aff = 0, likes = { "가면을 쓴 채 시작하는 살롱식 서두. 이름을 숨긴 대화의 긴장", "술잔을 나누며 서로의 허세를 가볍게 꼬집는 말놀이", "주도권을 쥐고 천천히 몰아가는 호흡. 신호는 그녀가 정한다", "끝난 뒤 가면을 벗는 순간의 짧은 침묵" }, limits = { "이름을 캐묻거나 가면을 억지로 벗기는 것, 신분을 폭로하는 말", "손님의 비밀을 거래 재료로 삼는 것", "금 십자 펜던트를 빼앗거나 모욕하는 것" }, needs = { "값을 먼저 치르고 시작한다(장미 골목의 규칙)", "격식을 지키는 손님. 서두르면 값을 올린다" }, ask = "……오늘은 가면을 벗고 말할게요. 값은 받지 않아요, 오늘만. 이름도 묻지 않을 테니, 오늘 밤은 저와 함께 있어 줄래요?", accept = "어서 와요. 가면은 쓰고 있어도 좋아요. 이름도 묻지 않을게요. ……자, 잔부터 받아요. 오늘 밤의 규칙은 내가 정해요.", decline = "후후, 현명한 거절이에요. 가면 쓴 손님을 놓아주는 것도 이 집의 예의죠. 다음에 올 때는 평소처럼 잔부터 받아요.", card = "가면 뒤에서 규칙을 정하고 천천히 몰아가는 살롱의 밤", detail = "29세. 마렌토식 살롱의 고급 접대부로, 이름을 묻지 않고 주도권을 쥐는 쪽이다. 신분을 캐거나 가면을 벗기는 것은 금지." },
} }

B.EN_RAW = [====[{" (보스는 절반)": " (half effect on bosses)", "25세. 앳되어 보이는 얼굴과 달리 일곱 해 경력의 노련한 접대부로, 말투와 태도는 성숙하다. 이야기를 들어 주는 것으로 시작한다.": "25 years old. Though her face looks young, she has seven years' experience as a courtesan and carries herself with mature poise. She begins by listening.", "29세. 마렌토식 살롱의 고급 접대부로, 이름을 묻지 않고 주도권을 쥐는 쪽이다. 신분을 캐거나 가면을 벗기는 것은 금지.": "29 years old. A high-end courtesan of a Marento-style salon, she keeps the guest's identity private and takes control. No prying into status or removing her mask.", "2턴 동안 받는 피해 −25%, 도발, <em>심연 −15</em>": "Damage taken −25% and taunt for 2 turns; <em>abyss −15</em>", "2턴 동안 받는 피해 −40%": "Damage taken −40% for 2 turns", "2턴 동안 받는 피해를 25% 줄이고 도발 상태가 된다(심연 −15).": "Take 25% less damage for 2 turns and taunt enemies (Abyss −15).", "2턴 충전 뒤 발동": "Activates after a 2-turn charge", "2턴 충전, 전체, 지정한 적 지연": "Charge for 2 turns; hit all enemies and delay the chosen target", "9회말 2아웃": "Bottom of the 9th, 2 Outs", "<em>심연 −40</em>": "<em>Abyss −40</em>", "B.G_rnd('intimacy|' + id + '|' + tries) 가 [0,100) 에서 나온 값 < 확률% 이면 성공 (tries 는 이번 시도 전 값)": "Success if B.G_rnd('intimacy|' + id + '|' + tries) yields a value in [0,100) < chance% (tries is the value before this attempt).", "HP 10% 소모, 다음 2회 공격이 연속 행동": "Spend 10% HP; the next 2 attacks grant extra actions", "HP 10% 소모, 다음 균열과 혼돈 파동의 심연 깎기 ×1.5": "Spend 10% HP; abyss damage from the next Rift and Chaos Wave ×1.5", "HP 10%를 치르고, 다음 2회의 공격을 연속 행동으로 이어서 한다.": "Sacrifice 10% HP, then make the next 2 attacks as consecutive actions.", "HP 10%를 치르고, 다음 균열과 혼돈 파동이 깎는 심연의 양을 ×1.5로 늘린다.": "Sacrifice 10% HP to increase the Abyss depletion of the next Rift and Chaos Wave by ×1.5.", "HP 15% 소모 → 치명 확률 +30%p · 치명 피해 +50%": "Spend 15% HP → Crit Chance +30%p · Crit Damage +50%", "HP 15%, 치명 +30%p (2턴), 치명 피해 +50%": "Spend 15% HP; critical chance +30 points and critical damage +50% for 2 turns", "HP 30% 이하 아군을 치유하면 회복량 +30%": "Healing +30% when healing an ally at 30% HP or lower", "HP 30% 이하에서 공격 +20%": "Attack +20% below 30% HP", "HP 30% 이하에서 심연 깎기 +25%": "Abyss depletion +25% while HP is 30% or lower", "HP 50% 이하에서 치명타 +15%": "Crit Chance +15% while HP is 50% or lower", "HP 50% 이하에서 회피 +15%": "Dodge +15% while HP is 50% or lower", "HP 50% 이하일 때 주는 피해": "Damage Dealt at 50% HP or Less", "HP 50% 이하일 때 주는 피해 +51%, 준 피해의 10%만큼 HP 회복": "At 50% HP or less, damage dealt +51%; recover HP equal to 10% of damage dealt", "HP {1}% 이하일 때 주는 피해 +{2}%, 준 피해의 {3}%만큼 HP 회복": "At {1}% HP or less, deal +{2}% damage and heal for {3}% of damage dealt", "HP 가 0 이 되는 일격을 받으면 최대 HP 50% 회복 — 파티원마다 전투당 1회(사제가 살아 있을 때)": "When a blow would reduce an ally's HP to 0, restore 50% of their maximum HP — 1 use per battle per party member (while the Priest is alive)", "HP 를 쓰는 스킬의 비용 -30%": "HP skill cost −30%", "HP가 70% 이상인 적에게 주는 피해가 +60% 커진다.": "Damage dealt to enemies at 70% HP or higher increases by +60%.", "HP가 {demon.thr%}% 이하일 때 공격 +{demon.atk%}%.": "At {demon.thr%}% HP or less, Attack +{demon.atk%}%.", "HP를 쓰는 스킬의 비용 -{morgas.hpc%}%.": "HP costs for skills -{morgas.hpc%}%.", "[제안] 동료 30명 + 마을 여성 6명 + 접대부 2명의 섹스 제안·성향 데이터. 사장님 확인 전. 정본 설명은 design/INTIMACY.md.": "[Proposed] Sexual invitation and preference data for 30 companions + 6 townswomen + 2 sex workers. Awaiting the owner's approval. The canonical description is in design/INTIMACY.md.", "a ≤ 100: round(12 + 0.7 * (a - 20))  (a=20 → 12, 50 → 33, 80 → 54, 100 → 68) · a > 100: round(68 + 0.3 * (a - 100))  (150 → 83, 200 → 98) — 최대 호감이 200 으로 늘었다(10-10). 100 이하는 예전 값 그대로, 위로는 완만하게 이어 total 의 95% 상한에서 멈춘다": "a ≤ 100: round(12 + 0.7 * (a - 20))  (a=20 → 12, 50 → 33, 80 → 54, 100 → 68) · a > 100: round(68 + 0.3 * (a - 100))  (150 → 83, 200 → 98) — maximum affection rose to 200 (10-10). Values at or below 100 stay the same; above that, the curve rises gently and stops at a cap of 95% of total.", "base + 개인 base(−20~+20) + 활성 mods 합 + retry_rest(−10) ": "base + personal base(−20~+20) + sum of active mods + retry_rest(−10)", "……가, 가문의 이름에 걸고 기쁘지 않다. ……하지만 거절하지도 않겠다. 손은, 치우지 않아도 된다.": "...On my family's name, I am not pleased. ...But I won't refuse. You can leave your hand there.", "……고마워요. 조건은 간단해요. 서로 멈추자고 하면 멈추는 것, 끝나고 나서 후회하지 않는 것. 안경은…… 당신이 벗겨 줘요.": "...Thank you. The terms are simple: we stop when either of us says stop, and we don't regret it afterward. My glasses... you take them off.", "……규칙대로 하자면 지금이 맞습니다. 아니, 규칙 때문이 아니라 제가 그러고 싶습니다. 불을 낮춰도 되겠습니까.": "...By the rules, the time is right. No—it's what I want, not what the rules say. May I dim the lights?", "……그런가. 무례했다면 사과하지. 이 일은 입 밖에 내지 않겠다. 내일 동문에서 평소처럼 보자.": "...I see. If I was rude, I apologize. I won't speak of this. See you at the east gate tomorrow, as always.", "……기록하지 않기로 했어요. 오늘 밤은요. 규칙은 내가 정해요. 신호는 은 펜 두 번 두드리기. 동의하면 위층으로 올라와요.": "...Tonight goes unrecorded. I set the rules. Two taps of the silver pen is the signal. If you agree, come upstairs.", "……묶어도 돼요? 손목에만, 풀기 쉬운 매듭으로. 신호는 두 번 두드리는 거예요.": "...May I tie you up? Just your wrists, with knots that come undone easily. Tap twice to stop.", "……밖으로 가자. 담요는 내가 챙길게. 추우면 말해.": "...Let's go outside. I'll bring the blanket. Tell me if you get cold.", "……본부장이 아니라 로레다나로 말할게요. 오늘 장부는 덮었어요. 당신이 괜찮다면, 오늘 밤은 계산 없이 보내고 싶어요.": "...Let me speak as Loredana, not the director. I've closed the books for today. If you want, I'd like to spend tonight with you without counting the cost.", "……비번이다. 부하들은 돌려보냈다. 용건만 말하겠다. 오늘 밤 내 방에 올 생각이 있나. 대답은 곧바로 해라.": "...I'm off duty. I sent my people home. I'll be direct: will you come to my room tonight? Answer me now.", "……안 한다. 그것만은 안 한다. 옆에 앉는 건 괜찮다.": "...No. I won't do that. You can sit beside me.", "……알겠어요. 기록하지 않을게요. 내일 기록관에서 평소처럼 봐요. 오늘의 제안은 없던 일로 해 둘게요.": "...Understood. I won't record it. I'll see you at the archives tomorrow as usual. Consider tonight's offer withdrawn.", "……알겠어요. 제안이 서툴렀네요. 장부에 적지 않을게요. 내일 창구에서 평소처럼 봐요.": "...I understand. I made that awkward. I won't put it in the ledger. I'll see you at the counter tomorrow, same as always.", "……오늘 밤 구간은 비웠습니다. 명령은 하지 않겠습니다. 대신…… 맡겨도 되겠습니까.": "...I've cleared tonight's watch. I won't give orders. Instead... may I leave things to you?", "……오늘 아침 숟가락 안 떨어뜨렸고, 길도 오른쪽이었어요. 좋아요, 징조가 허락했으니까. 부적은 거기 두고요.": "...I didn't drop my spoon this morning, and the path bent right. Good omens. Leave the charm there, then.", "……오늘은 가면을 벗고 말할게요. 값은 받지 않아요, 오늘만. 이름도 묻지 않을 테니, 오늘 밤은 저와 함께 있어 줄래요?": "...I'll take off my mask to ask. No charge, just for tonight. I won't ask your name either. Will you stay with me?", "……오늘은 등불을 다 닦았어요. 괜찮다면 안쪽 방에서 좀 쉬었다 가요. 쉬는 것만이 아니라…… 그 이상이라도, 오늘은 괜찮아요.": "...I've cleaned every lantern. If you'd like, come rest in the back room. And if rest turns into... more, I'd like that too.", "……오늘은 문을 일찍 닫았어요. 위층 방은 비어 있고, 국도 남았고요. ……올라와서 같이 있을래요? 말은 안 해도 돼요.": "...I closed early tonight. The room upstairs is free, and there's soup left. ...Would you come up and stay with me? We don't have to talk.", "……오늘은 안 돼요. 실이 안 풀려요. 다음에.": "...Not today. The yarn won't come loose. Another time.", "……오늘은 장부에 적지 않을게요. 값 없이, 그냥 당신이라서요. 단골 이름을 하나하나 적어 온 제가, 처음으로 장부 밖에서 묻는 거예요. 위층으로 올라가 볼래요?": "...No entry in the ledger tonight. No price; just you. I've written down every regular's name, but this is the first thing I've asked outside the books. Will you come upstairs?", "……이번 건 값을 안 받을게요. 대신 참을 줄 아는 사람인지 보죠. 신호는 제가 정해요.": "...No charge for this one. But let's see if you know how to wait. I set the signal.", "……인장을 풀겠습니다. 이건 서약에는 적혀 있지 않은 일이니까요. 웃기 시작하면 도와주십시오. 멈추지 않을지도 모릅니다.": "...I'll remove my seal. This isn't covered by the oath. If I start laughing, help me. I may not be able to stop.", "……저, 저 말이죠. 둘이서만 있을 때라면, 괜찮아요. 아, 귀는 만지지 말……는 건 아니고, 천천히요.": "...I mean, if it's just us, then yes. Don't touch my ears—no, I didn't mean that. Just... slowly.", "……제, 제가 부탁해도 돼요? 손목을…… 묶어 주세요. 그러면 아무것도 안 부서질 것 같아서요. 풀고 싶으면 제가 말할게요.": "...M-may I ask you something? Tie my wrists... please. Then I won't break anything. I'll tell you when I want them free.", "……좋다. 방은 이쪽이다. 규칙은 하나, 멈추라고 하면 즉시 멈출 것. 흉터는 건드려도 된다. 천천히.": "...Yes. My room is this way. One rule: if I say stop, you stop at once. You may touch the scar. Gently.", "……좋아요. 첫 번째 규칙, 내가 말하기 전에는 아무것도 하지 않을 것. 두 번째, 멈추고 싶으면 두 번 두드릴 것. ……뿔은 물어보고 만져요.": "...All right. First rule: do nothing until I say so. Second: tap twice if you want to stop. ...Ask before touching my horns.", "……죄, 죄송해요. 지금은 안 돼요. 싫다기보다…… 아니에요, 안 돼요. 그만 물어봐 주세요.": "...S-sorry. I can't right now. It's not that I don't... No. I can't. Please stop asking.", "……죄송합니다. 지금은 구간 책임이 남아 있습니다. 거절입니다.": "...I'm sorry. I'm still responsible for this stretch of the line. No.", "……죄송합니다. 지금은 소설의 규칙으로도, 제 규칙으로도 아니라는 답이 나옵니다. 다음 장을 기다려 주시겠습니까.": "...I'm sorry. By the rules of the novel and by my own, the answer is no. Will you wait for the next chapter?", "……죄송합니다. 지금은 인장이 식지 않았습니다. 거절합니다.": "...I'm sorry. My seal is still warm. No.", "……지금은 아니오. 이유는 묻지 마시오. 제3조를 되뇌고 있다는 것만 알아 두시오.": "...Not now. Don't ask why. Just know that I'm reciting Clause 3 to myself.", "……찾아 주세요. 제가 숨을 테니까, 못 찾으면 제가 나올게요. 그 대신 거미 없는 곳이어야 해요.": "...Find me. I'll hide, and if you can't find me, I'll come out. But no spiders. Promise.", "……춥다. 그러니까…… 우연이 아니다. 오늘은 우연이라고 안 할 거다.": "...It's cold. So... this isn't an accident. I won't call it one tonight.", "★ 등급이 배수를 곱한다(design/FORMULA.md 「난이도 등급」)": "The ★ grade applies a multiplier (design/FORMULA.md, \"Difficulty Grades\").", "「개」 같은 비하와 가문의 이름을 조롱하는 호칭": "Slurs like “dog” or names that mock her family", "「고갈된 뒤에도 파동은 멎지 않는다. 속이 빈 곳은 작은 떨림도 멀리까지 울려.」": "「Even after depletion, the wave does not cease. In a hollow place, the smallest tremor carries far.」", "「균열은 겉에서 재면 얕아 보여. 손을 뻗어 봐야 어디까지 이어지는지 알지.」": "「Measure a rift from its edge and it looks shallow. Reach into it to learn how far it runs.」", "「그라벤 문을 나서기 전에 돌아올 때 쓸 약부터 챙겨. 전선이 두 개라 아무도 기다려 주지 않으니까.」": "「Before you leave Graben's gate, pack the medicine for your return. There are two fronts, and neither will wait for you.」", "「기도가 앞줄에서 끊기면 뒷줄은 누가 돌보겠나. 이름 모르는 사람까지 빠짐없이 불러 줘라.」": "「If prayer stops at the front rank, who tends the rear? Call every name, even those you do not know.」", "「기도를 마친 손이라도 시위는 제 힘으로 당겨야지. 곁에 선 사람은 다음 화살만 건네주면 돼.」": "「Even hands fresh from prayer must draw the string themselves. The one beside you need only pass the next arrow.」", "「기록합니다」로 시작하는 합의 의식. 문장으로 정리된 동의": "A ritual of consent beginning “For the record,” with every term in writing", "「나를 보라고 외쳐라. 적의 눈이 이쪽으로 쏠리면 뒤에 선 사람들이 숨을 돌린다.」": "「Call out for them to look at you. When the enemy's eyes turn your way, those behind you can catch their breath.」", "「나무는 억지로 키우는 게 아니야. 마법도 뿌리가 닿은 만큼만 뻗는다.」": "「You cannot force a tree to grow. Magic reaches only as far as its roots.」", "「내 것」「네 것」을 선언하는 소유와 귀속 역할극": "Possession roleplay declaring “mine” or “yours”", "「내 기도가 끝나기를 기다리지 마라. 내가 손을 들면 먼저 움직여, 뒤는 내가 막는다.」": "「Don't wait for me to finish praying. When my hand rises, move. I will cover what follows.」", "「다시 해 봐」 같은 반복 요구, 시험하는 말": "Demands to “do it again” or words that test her", "「두 신은 하나였다」는 녹스 교리를 따라 군대와 함께 다니는 사제. 케른 밖에서는 이단이라는 소리를 듣고, 설 신전도 없다": "A traveling Priest of the Nox creed that the two gods were once one. Beyond Kern, she is called a heretic and has no temple to call her own.", "「루미엘로 난 문은 대관식 때만 열린다. 그날이라도 시위는 풀지 마라.」": "「The road to Lumiel opens only for a coronation. Keep the bowstring taut even then.」", "「막사 밖에서 올려도 기도는 기도다. 다친 사람을 돌보는 데 사당까지는 필요 없다.」": "「Prayer outside the barracks is prayer all the same. You need no shrine to tend the wounded.」", "「맞혔으면 곧장 다음 화살을 꺼내. 맞히고 나서 숨 돌리면 남은 적에게 차례를 내주는 거야.」": "「If it hits, take out the next arrow. Pause to breathe, and you've given the remaining enemy a turn.」", "「무레나 공방에서 불이 나거든 문부터 찾아라. 다른 사람 발도 다 그쪽으로 달리니까.」": "「If fire breaks out in a Murena workshop, find the door first. Everyone else's feet will be running for it too.」", "「무레나에서 불이 나면 유리병부터 세지 마라. 사람을 먼저 문 밖으로 내보내.」": "「When Murena burns, don't count the glass bottles. Get the people through the door first.」", "「발로아에서는 배에 오른 사람이 어디서 왔는지 묻지 않는다. 같이 노 저을 손이 있는지만 묻는다.」": "「In Valois, we don't ask where a sailor boarded from. Only whether they have hands enough to row beside us.」", "「방패 하나가 가리는 건 한 사람이다. 어깨를 맞대면 그 뒤에 선 사람까지 가려진다.」": "「One shield covers one person. Stand shoulder to shoulder, and it covers the ones behind you too.」", "「벨모르의 불은 밤새 꺼지지 않는다. 칼 든 손도 그만큼은 버텨야 해.」": "「Belmor's fires burn through the night. The hand on the sword had better last as long.」", "「병을 던질 자리를 잘 골라라. 튄 약이 어디까지 닿는지는 병 바닥을 본 사람이 제일 먼저 안다.」": "「Choose carefully where you throw the vial. Whoever has looked at its bottom knows where the splash will reach.」", "「보호막이 깨지는 소리가 들리거든 손부터 뻗어라. 새 방패를 세우는 건 다친 사람을 붙잡은 다음이다.」": "「When you hear a shield break, reach out. Catch the wounded first; then raise another wall.」", "「분열 후」라는 말을 꺼내는 것": "Mentioning “After the Sundering”", "「상대 차례 지연」 8% → 20%, 마력 폭발로 지정한 적 25% → 50%. 늦춘 시간의 55%만큼 자신의 다음 차례가 빨라진다": "\"Delay Enemy Turn\" 8% → 20%; target of Arcane Explosion 25% → 50%. Advance your next turn by 55% of the time delayed", "「상대 차례 지연」 8% → {1}%, 마력 폭발로 지정한 적 25% → {2}%. 늦춘 시간의 {3}%만큼 자신의 다음 차례가 빨라진다": "Enemy turn delay: 8% → {1}%; Mana Burst's chosen target: 25% → {2}%. Advance your next turn by {3}% of the time stolen", "「상처를 덮는 손이 약해 보여도 그 손을 건드리면 성벽 전체가 돌아선다.」": "「A hand dressing a wound may look weak. Strike it, and the whole wall turns to face you.」", "「성과급 챙기기」": "Performance Bonus", "「쇠는 깨져도 맹세는 안 깨진다. 누가 먼저 물러설지는 우리끼리 정한다.」": "「Iron may break. An oath does not. We'll decide among ourselves who steps back first.」", "「시위를 놓기 전엔 바람이 몇 번 바뀌어도 괜찮다. 놓는 그 순간만큼은 바람이 한 방향이어야 해.」": "「The wind may shift a dozen times before you loose. At that one instant, let it blow in only one direction.」", "「신전의 시험이 평생 앉을 자리를 정해 줄지언정, 투구 안에서 내리는 결정까지 대신해 주진 않아.」": "「The temple's test may decide where I sit for life. It cannot make the choice I face inside this helm.」", "「실바렌 공터에서는 씨족 이름을 묻기 전에 짐부터 내려놔. 같이 들어야 멀리 간다.」": "「At Silvaren's clearing, put down the load before asking a clan name. You'll carry it farther together.」", "「아르카스에서는 왕궁과 대성당이 서로 마주 본다. 어느 쪽 창문이 먼저 닫히는지 눈여겨봐 둬.」": "「In Arcas, palace and cathedral face each other. Watch which windows close first.」", "「알트 계곡에서는 약속을 쇳조각으로 남긴다. 다 지키지 못할 것 같으면 돌아올 길부터 그려 둬라.」": "「In Alt Valley, promises are marked in iron. If you cannot keep every one, draw the way home first.」", "「약 아끼다 사람을 잃으면 병 바닥에 한 방울 남은들 무슨 소용이야. 필요한 만큼 따라 줘.」": "「If hoarding medicine costs a life, what use is the last drop in the bottle? Pour what is needed.」", "「얄친 고개는 혼자 넘을 수 있어도, 뒤따라올 발자국까지 혼자 남길 수는 없다.」": "「You can cross Yalchin Pass alone. You cannot leave the footprints of everyone coming after you.」", "「엎친 데 덮친 격」": "It Rains, It Pours", "「이제 해도 됩니까」 하고 물어 주고 대답을 기다려 주는 사람": "Someone who asks “May I?” and waits for her answer", "「지킬 사람이 남아 있는 동안은 검을 거둘 때가 아니다. 방패 뒤에 숨으라는 말도 입에 올리지 마라.」": "「While someone remains to protect, this is no time to sheath a sword. And don't tell me to hide behind a shield.」", "「처음부터 피를 흘릴 필요는 없어. 끝나고도 제 발로 걸어 나와서 다음 싸움에 칼을 쥐고 있어야지.」": "「You needn't bleed from the beginning. Walk out on your own feet, with strength to hold a sword in the next fight.」", "「천막 줄 끝에 새 이름을 적는다고 옛 이름이 지워지지는 않아.」": "「Writing a new name at the end of the tent line doesn't erase the old one.」", "「철수로도 계약에 넣어. 살아 돌아와야 다음 일을 맡지.」": "「Put the retreat route in the contract. You have to come back alive to take the next job.」", "「첫 방울은 눈에 띄지도 않아. 걷어 낼 때를 놓쳤구나 싶을 즈음엔 다음 방울이 벌써 스며 있지.」": "「You won't notice the first drop. By the time you wish you'd wiped it away, the next has soaked in.」", "「첫 칼로 눈길을 끌어. 다음 칼은 그림자가 놓을 테니, 상대가 돌아설 때면 이미 늦었지.」": "「Draw their eyes with the first blade. The shadow carries the second. By the time they turn, it is too late.」", "「칸의 깃발 아래에서는 누가 쓰러지면 그 자리를 곧장 메워야 해. 사냥도 전쟁도 기다려 주지 않으니까.」": "「Beneath the khan's banner, a fallen fighter's place must be filled at once. Neither hunt nor war waits.」", "「타른 계곡에서 배운 마법은 다 쓰고 나서도 돌아갈 몫을 남겨 둔다. 쇠 맹세가 그렇듯이.」": "「Magic learned in Tarn Valley leaves something for the journey home, even after it has been spent. Just like an Iron Oath.」", "「타이겐 성 안에서는 부족 깃발을 보고, 성 밖에서는 말발굽 소리를 들어라.」": "「Inside Taigen, watch the tribal banners. Outside, listen for hooves.」", "「타이겐 성 안의 부족이나 성 밖의 상인이나 같은 겨울을 난다. 성문을 걸어 잠글 때 그걸 잊지 마라.」": "「The tribes inside Taigen and the merchants outside it endure the same winter. Remember that before you bar the gate.」", "「토르바에서 약이 달리거든 계약서부터 들추지 마. 가마솥에 불부터 지펴.」": "「If Torva runs short of medicine, don't reach for the contract first. Light the fire beneath the cauldron.」", "「하나 쓰러뜨렸다고 멈추지 마. 다음 발자국이 지워지기 전에 몸부터 돌려.」": "「One fallen quarry is no reason to stop. Turn before the next tracks fade.」", "「한 번만 더 해 봐요」를 반복하는 집요함": "Insisting “Just one more time” again and again", "「한 줄씩 지워질 때는 참을 만하지. 겹쳐 있던 줄이 한꺼번에 사라지면 숨도 못 쉰다.」": "「One line fading at a time can be borne. Let all the overlapping lines vanish at once, and there's no breath left to draw.」", "「흑요 신전선에서는 불이 길을 밝힌다. 어둠을 찾는 거라면 해자 건너편을 봐라.」": "「On the Obsidian Temple Line, fire lights the road. If you seek darkness, look beyond the moat.」", "「흑요 신전선을 지키려면 앞만 봐서는 안 돼. 해자와 성문까지 같이 살펴라.」": "「To hold the Obsidian Temple Line, don't stare only ahead. Watch the moat and gate as well.」", "「힘을 넓게 펼치면 벽이 흔들리는 데서 끝난다. 한 점에 모으면 돌도 쪼개지니, 쏟아낼 때를 기다려.」": "「Spread power wide and you may shake a wall. Gather it at a single point and you can split stone. Wait for the moment to let it go.」", "가느다란 귀걸이": "Slender Earring", "가느다란 브로치": "Slender Brooch", "가느다란 수정 반지": "Slender Crystal Ring", "가느다란 은빛 고리": "Slender silver band", "가느다란 은팔찌": "Slender Silver Bracelet", "가느다란 푸른 보석": "Slender Blue Gem", "가는 은반지": "Fine Silver Band", "가라앉은 종": "Sunken Bell", "가로 놓인 활대": "Crosswise bow stave", "가르듯 베어": "slashed", "가면 뒤에서 규칙을 정하고 천천히 몰아가는 살롱의 밤": "A salon night of masked rules and slow, sure control", "가면 축제": "Festival of Masks", "가면을 쓴 채 시작하는 살롱식 서두. 이름을 숨긴 대화의 긴장": "A masked salon greeting, charged by the secret of an unknown name", "가면의 집": "House of Masks", "가문의 이름을 존중하는 호칭으로 불러 주는 것": "Being addressed with respect for her family name", "가벼운 목걸이": "Light Necklace", "가벼운 문장": "Light Crest", "가벼운 수정봉": "Light Crystal Rod", "가벼운 은반지": "Light Silver Band", "가벼운 투구": "Light Helm", "가벼운 호박 귀걸이": "Light Amber Earring", "가볍게 건네는 말도 받아 준다. 진심이면 더 쉽게 열린다": "She can take a lighthearted invitation, and sincerity opens her up further", "가성비 처방": "Budget Prescription", "가시 방벽": "Thornwall", "가시 성지": "Thornbound Sanctuary", "가시 순례자": "Thorn Pilgrim", "가시 폭발": "Thornburst", "가시나무 무색홀": "Thornwood Colorless Scepter", "가시나무 복합궁": "Thornwood Composite Bow", "가시나무 수정봉": "Thornwood Crystal Rod", "가시나무 조제홀": "Thornwood Apothecary Scepter", "가시나무 지팡이": "Thornwood Staff", "가시덩굴에 휘감긴 채 성지를 향해 걷는 순례자": "A pilgrim walking toward the holy site despite the thorns wrapped around them", "가시덩굴이 뚫고 나온 유물함": "A reliquary split open by thorn vines", "가시로 찔렀다": "pierced with thorns", "가시를 쏟아냈다": "rained thorns", "가시를 터뜨렸다": "detonated its thorns", "가시무늬 곡검": "Thorn-Marked Scimitar", "가시무늬 전투망치": "Thorn-Marked Warhammer", "가시무늬 제례칼": "Thorn-Marked Ritual Knife", "가시뿌리 울타리": "Thornroot Hedge", "가장 소심한 사람이 가장 강한 힘을 지녔고, 그래서 잠자리에서는 스스로 묶이길 원한다. 손이 묶여 있으면 아무것도 부수지 않는다는 안도감 때문이다. 이것은 속박이 아니라 안전하게 쉬는 방법이고, 그 부탁을 입 밖에 내는 것 자체가 가장 큰 신뢰의 표시다.": "The most timid woman has the strongest power, and so she asks to be bound in bed. With her hands tied, she can rest knowing she will break nothing. For her it is a way to feel safe, and asking for it aloud is her deepest show of trust.", "가죽 감은 무색홀": "Leather-Wrapped Colorless Scepter", "가죽 감은 수정봉": "Leather-Wrapped Crystal Rod", "가죽 감은 연금봉": "Leather-Wrapped Alchemy Rod", "가죽 감은 지팡이": "Leather-Wrapped Staff", "가죽 끈으로 돌을 돌리는 부족 전사": "A tribal warrior whirling a stone in a leather sling", "가죽 수놓은 장화": "Leather-Embroidered Boots", "가죽 어깨보호구": "Leather Shoulder Guards", "가죽 외투": "Leather Coat", "가죽 표지에 이빨이 돋은 두꺼운 책": "A thick leatherbound book with teeth sprouting from its cover", "가죽끈 단궁": "Leather-Strung Shortbow", "각진 망치 머리": "Angular hammer head", "간지럼과 농담이 허용되는 밤": "A night where tickling and jokes are welcome", "간지럼과 서로 놀리기": "Tickling and teasing each other", "갇힌 길드 탐사대에게 닿는 길을 막은 균열의 적을 물리친다.": "Defeat the rift creatures blocking the path to the trapped guild expedition.", "갈고리": "Hook", "갈고리를 휘둘렀다": "swung a hook", "갈기가 얼음으로 굳은 거대한 설표": "A giant snow leopard with an icebound mane", "갈대무늬 갈고리칼": "Reed-Marked Hookblade", "갈대무늬 마도 조끼": "Reed-Marked Arcane Vest", "갈대무늬 문장": "Reed-Marked Crest", "갈대무늬 별무늬 반지": "Reed-Marked Star-Marked Ring", "갈대배 노잡이 떼": "Reedboat Oarsmen", "갈대배째 가라앉은 노잡이들. 노를 무기처럼 휘두른다": "Oarsmen who sank with their reed boat, swinging oars as weapons", "갈라": "rended", "갈라진 끝의 봉": "Rod with a split tip", "갈랐다": "rended", "갈색 가죽 조끼": "Brown Leather Vest", "갈색 방패 갑옷": "Brown Shield Armor", "갈색 수놓은 장화": "Brown Embroidered Boots", "갈색 어깨갑옷": "Brown Pauldrons", "갈색 어깨옷": "Brown Mantle", "갈색 자수 로브": "Brown Embroidered Robe", "갈증의 구리 팔찌": "Copper Bracelet of Thirst", "갉기": "Gnaw", "갉았다": "gnawed", "감시관": "Overseer", "감싸기": "Protect", "감정 없는 계약 암살자가 잠자리에서는 가장 철저한 복종자가 된다. 합의한 범위 안에서는 한 치도 어기지 않고 따른다. 케른의 맹세는 문구를 지키는 것이니, 믿는 상대에게 문구대로 자신을 내주는 것이 그녀가 사랑을 표하는 방식이다.": "The seemingly unfeeling contract Assassin submits completely in bed, following every agreed term without deviation. A Kern oath is fidelity to its wording; giving herself to someone she trusts by those very words is how she shows love.", "감정을 흔들 수 있는 자리여야 한다. 공식적인 분위기에서는 웃음을 참는다": "She needs a place where she can let herself feel; in formal settings she stifles her laughter", "감정적인 호소는 통하지 않는다. 조건과 신뢰가 갖춰졌을 때만 받는다": "Emotional appeals will not work. Only trust and clear terms will", "갑옷과 십자 문장을 장난감처럼 쓰거나 더럽히는 연출": "Using her armor or cross insignia as a toy, or defiling them", "갑옷을 하나씩 풀어 주는 손길": "Hands unfastening each piece of armor", "값 얘기가 아니고, 오늘은 안 합니다. 선 긋는 거예요. 다음에 다시 말해요.": "This isn't about money. Not tonight. I'm drawing a line. Ask another time.", "값부터 따지던 사람이 값을 말하지 않는 밤을 허락한다. 애태우고 참게 하는 조율을 즐기며, 약물과 돈으로 사려는 시도는 단칼에 거절한다.": "The woman who used to name a price allows one night without one. She enjoys patient teasing and control, but rejects drugs and any attempt to buy her.", "값은 말하지 않고, 조율로 애태우는 은밀한 밤": "A secret night of patience and delicious anticipation, with no price named", "값을 깎거나 흥정으로 다른 손님과 비교하는 말": "Haggling over her price or comparing her with other clients", "값을 말하지 않는 단 한 사람만을 위한 시간": "Time given to one person alone, with no price named", "값을 먼저 치르고 시작한다(장미 골목의 규칙)": "Payment comes first, by the rules of Rose Alley", "강건": "Fortitude", "강을 건너온 금반지": "River-Crossing Gold Band", "강을 건너온 로브": "River-Crossing Robe", "강을 건너온 수정봉": "River-Crossing Crystal Rod", "강을 건너온 어깨옷": "River-Crossing Mantle", "강을 건너온 은팔찌": "River-Crossing Silver Bracelet", "강을 건너온 장식": "River-Crossing Ornament", "강을 건너온 펜던트": "River-Crossing Pendant", "강을 건너온 향로봉": "River-Crossing Censer Staff", "강의실 천장에 닿는 강사 인형. 칠판 셋을 등에 지고, 끝나지 않는 강의를 한다.": "A lecturer automaton tall enough to touch the ceiling. Three blackboards hang from its back as it delivers an endless lesson.", "강철 곡검": "Steel Scimitar", "강철 대검": "Steel Greatsword", "강철 손쇠뇌": "Steel Hand Crossbow", "강철 장검": "Steel Longsword", "강철 제례칼": "Steel Ritual Knife", "강타": "Heavy blow", "강타했다": "dealt a heavy blow", "같은 깃발 조항": "Same-Banner Clause", "같은 레벨의 표준 잡몹": "Standard mob of the same level", "같은 식탁에서 한 끼를 먹는다": "Share a meal at the same table", "같은 적에게 지속 피해 최대 5겹(엔진 값 · 10-10)": "Damage over time stacks up to 5 times on the same enemy (engine value · 10-10)", "같은 적을 연달아 공격할 때마다 주는 피해가 5%씩 쌓인다(최대 +50%). 다른 적을 공격하면 처음부터 다시 쌓는다.": "Each consecutive attack on the same enemy adds 5% damage (up to +50%). Attacking another enemy resets the buildup.", "같은 적을 연속 공격하면 피해 누적 +8%": "Consecutive attacks against the same enemy add +8% cumulative damage", "같은 휴식 안에서 이미 한 번 거절당한 뒤의 재제안(전원 공통 −10, 개인 값은 여기에 더한다)": "Asking again after a refusal during the same rest (−10 for everyone; add personal modifier)", "개": "Hound", "개 계통만 비교적 받아들여진다": "Canines are accepted more readily", "개 취급, 귀와 꼬리를 놀리는 것": "Treating her like a dog or mocking her ears and tail", "개과": "Canine", "개인 스킬: 2턴 동안 받는 피해 −25%, 도발, <em>심연 −15</em>": "Unique skill: Damage taken −25% and taunt for 2 turns; <em>abyss −15</em>", "개인 스킬: HP 10% 소모, 다음 2회 공격이 연속 행동": "Unique skill: Spend 10% HP; the next 2 attacks grant extra actions", "개인 스킬: HP 10% 소모, 다음 균열과 혼돈 파동의 심연 깎기 ×1.5": "Unique skill: spend 10% HP; abyss damage from the next Rift and Chaos Wave ×1.5", "개인 스킬: 단일 ×1.4, 디버프가 걸린 적에게 +40%": "Unique skill: Single target ×1.4; +40% against debuffed enemies", "개인 스킬: 방어↓, 속도↓, 공격↓ 3개를 차례로 걸고 부식 +1, <em>심연 −3</em>": "Unique skill: Apply defense, speed, and attack penalties, one corrosion stack; <em>abyss −3</em>", "개인 스킬: 아군 1명 대신 다음 적 공격 1회를 맞고, 받는 피해 −30%": "Unique skill: take the next enemy hit for an ally; damage taken −30%", "개인 스킬: 아군 1명 소량 회복(지능 ×0.4), 디버프 1개 해제": "Unique skill: Heal one ally (Intelligence ×0.4) and remove one debuff", "개인 스킬: 아군 1명 회복(잃은 HP가 클수록 더 많이), 디버프 1개 해제": "Unique skill: Heal one ally more when HP is low; remove one debuff", "개인 스킬: 아군 1명 회복, 그 사람의 다음 차례 30% 당김": "Unique skill: Heal one ally and advance their next turn by 30%", "개인 스킬: 아군 1명의 버프 하나를 두 배로(지속 시간 그대로)": "Unique skill: Double one ally buff without changing its duration", "개인 스킬: 아군 전체 HP 회복 + 다음 2라운드 재생": "Unique skill: Heal all allies and grant regeneration for the next 2 rounds", "개인 스킬: 아군 전체 공격 또는 방어 +15% (2턴)": "Unique skill: All allies: attack or defense +15% for 2 turns", "개인 스킬: 아군 전체 소량 회복, 2턴 동안 받는 피해 −10%와 재생, 쓰러지면 사라짐": "Unique skill: Heal all allies slightly; damage taken −10% and regeneration for 2 turns", "개인 스킬: 아군 전체 회복 + 보호막(각각 절반 효과)": "Unique skill: Heal and shield all allies, each at half strength", "개인 스킬: 위력 ×1.2, <em>심연 −15</em>, 덫(명중한 적의 공격 −20%, 2턴)": "Unique skill: Power ×1.2; <em>abyss −15</em>; snare reduces enemy attack by 20% for 2 turns", "개인 스킬: 위력 ×1.2, <em>심연 −15</em>, 쓰러뜨리면 MP 6 회복": "Unique skill: Power ×1.2; <em>abyss −15</em>; recover 6 MP on a kill", "개인 스킬: 위력 ×1.2, <em>심연 −15</em>, 주문, 약화, 소환 중 하나를 예고한 적 +30%": "Unique skill: Power ×1.2; <em>abyss −15</em>; +30% against an enemy telegraphing a spell, debuff, or summon", "개인 스킬: 자신과 같은 줄 아군 받는 피해 −20% (3턴), 쓰러지면 사라짐": "Unique skill: Allies in your row take −20% damage for 3 turns; ends if you fall", "개인 스킬: 적 1명 <em>심연 −40</em>, 2턴 도발": "Unique skill: One enemy: <em>abyss −40</em>; taunt for 2 turns", "개인 스킬: 적 1명에 표식을 남겨, 그 적이 받는 다음 공격은 확정 치명타. <em>심연 −3</em>": "Unique skill: mark one enemy. The next hit against it is a guaranteed critical; <em>abyss −3</em>", "개인 스킬: 적 1명에게 위력 ×1.2, <em>심연 −15</em>": "Unique skill: Hit one enemy at ×1.2 power; <em>abyss −15</em>", "개인 스킬: 적 1명에게 위력 ×1.2, <em>심연 −15</em>, 계약 표식 대상 +40%": "Unique skill: Hit one enemy at ×1.2 power; <em>abyss −15</em>; +40% against a marked target", "개인 스킬: 적 1명에게 위력 ×1.2, 내가 가장 빠르면 피해 +50%, <em>심연 −15</em>": "Unique skill: Hit one enemy at ×1.2 power; +50% damage if you act first; <em>abyss −15</em>", "개인 스킬: 적 1명에게 지능 ×1.2, 다음 아군 마법 피해 +10%, <em>심연 −15</em>": "Unique skill: Hit one enemy for Intelligence ×1.2; next allied magic damage +10%; <em>abyss −15</em>", "개인 스킬: 적 1명의 다음 차례를 40% 뒤로, <em>심연 −3</em>": "Unique skill: Delay one enemy by 40%; <em>abyss −3</em>", "개인 스킬: 적 1명의 마법 공격 2턴 봉인, <em>심연 −15</em>": "Unique skill: Seal one enemy magic attack for 2 turns; <em>abyss −15</em>", "개인 스킬: 적 전체 ×1.2, <em>심연 −15씩</em>, 내 방어 1턴 −20%": "Unique skill: All enemies ×1.2; <em>abyss −15 each</em>; your defense −20% for 1 turn", "개인 스킬: 적 전체 공격 −15%, 자신은 도발(3턴), <em>심연 −20씩</em>": "Unique skill: All enemies: attack −15%; taunt for 3 turns; <em>abyss −20 each</em>", "개인 스킬: 전투당 1회, 충전 없이 마력 폭발을 바로 발동, 적 전체 ×1.9": "Unique skill: once per battle, cast Arcane Burst instantly against all enemies ×1.9", "개인 스킬: 표적과 그 뒤의 적 1명을 ×1.3씩 꿰뚫는다, <em>심연 −3씩</em>": "Unique skill: Pierce the target and one enemy behind it for ×1.3 each; <em>abyss −3 each</em>", "거대 딱정벌레 떼": "Giant Beetle Swarm", "거절! 대신 저녁은 같이 먹어요. 그건 언제나 열려 있어요.": "No! But have supper with me. That invitation is always open.", "거절이에요. 값을 더 얹어도 마찬가지고, 깎아 달라 해도 마찬가지예요.": "No. Offering more money or asking for a discount won't change that.", "거절이에요. 설득해도 결과는 안 바뀌어요. 다음 실험 때 다시 신청하세요.": "No. Persuading me won't change the result. Apply again for the next experiment.", "거절입니다. 추가 보수를 제시하셔도 마찬가지입니다. 이건 보수의 문제가 아닙니다.": "No. Extra pay won't change it. This isn't about compensation.", "거절하는 거요. 농담으로 흘리려는 게 아니라 정식으로. 이단도 싫다는 말은 할 줄 안다오.": "I'm refusing, formally, not making a joke. Even a heretic knows how to say no.", "거절하오. 제안서의 조항이 아직 비어 있소. 이대로는 서명할 수 없소.": "Declined. The proposal still has blank clauses. I cannot sign it as it stands.", "거절합니다. 일은 일이고 이건 일이 아니라서요. 더 설명은 안 합니다.": "I refuse. Work is work, and this isn't work. I won't explain further.", "거절합니다. 재신청은 받습니다. 천천히 하세요.": "Declined. You may apply again. Take your time.", "거짓 기적": "False Miracle", "거짓 축복": "False Blessing", "거창한 이름을 붙여 외치는 주문. 적 1명에게 지능 ×1.2의 피해를 주고, 다음 아군 마법의 피해를 +10% 높인다(심연 −15).": "A spell shouted under a grandiose name. Deal Intelligence ×1.2 damage to 1 enemy and increase the damage of the next allied spell by +10% (Abyss −15).", "거친 귀걸이": "Rough Earring", "거친 나무 활대": "Rough wooden bow stave", "거친 두건": "Rough Hood", "거친 로브": "Rough Robe", "거친 목걸이": "Rough Necklace", "거친 부적": "Rough Charm", "거친 붉은 보석": "Rough Red Gem", "검은 마도 조끼": "Black Arcane Vest", "검은 바늘 반지": "Black Needle Ring", "검은 브로치": "Black Brooch", "검은 비늘 갑옷": "Black Scale Armor", "검은 수정봉": "Black Crystal Rod", "검은 수정이 박힌 봉": "Rod set with black crystal", "검은 수정이 박힌 지팡이": "Staff set with black crystal", "검은 어깨옷": "Black Mantle", "검은 창": "Black Spear", "검은 학자 외투": "Black Scholar's Coat", "검은빛 기사창": "Dark Lance", "검은빛 성검": "Dark Holy Sword", "검은빛 쌍검": "Dark Twin Blades", "검투사": "Gladiator", "검푸른 망토": "Midnight Blue Cloak", "검푸른 은반지": "Midnight Blue Silver Band", "검푸른 짧은 망토": "Midnight Blue Short Cloak", "겉으로는 규칙대로 사는 성기사지만, 몰래 읽는 연애 소설에는 저만의 규칙표가 있다. 단계를 지켜야 마음이 열리고, 제일 아끼는 장면은 쫓기다 붙잡히는 대목이다. 평생 도망쳐 본 적 없는 사람이 규칙을 의심하기 시작한 뒤로는 「붙잡혀서라도 멈추는」 장면에 마음이 놓인다.": "Outwardly, this Paladin lives by the rules. In secret romance novels she has found a different rulebook, and she needs each step in order before she can let someone close. Her favorite passage is the chase that ends in capture. Having never run from anything, she now finds comfort in the thought of being caught and made to stop questioning.", "게르다": "Gerda", "게르다 바이트만": "Gerda Weidmann", "겔렌하임": "Gellenheim", "겔렌하임 궁정은 변경 병력 할당을 두고 오래 다퉜다. 그 긴 논쟁 내내 심연 쪽 성벽은 제자리에 서 있었다.": "Gellenheim's court argued long over troops for the March. Through every word of the quarrel, the wall facing the Abyss stood where it was.", "겔렌하임 궁정은 병력 할당표를 해마다 늦게 확정한다. 변경령 보초는 서명이 끝나기도 전에 성벽에 올라 있다.": "Gellenheim's court settles its troop quotas late every year. The March's sentries are on the wall before the ink is dry.", "겔렌하임 궁정은 해마다 변경 병력을 두고 다툰다. 올해 장부가 닫히기 전에 성벽에 먼저 닿는 건 누구일까.": "Each year Gellenheim's court quarrels over border troops. Who will reach the wall before this year's ledger closes?", "겔렌하임의 다음 일격": "Next Strike of Gellenheim", "겔렌하임의 되찾은 숨": "Restored Breath of Gellenheim", "겔렌하임의 반지": "Ring of Gellenheim", "겔렌하임의 버티는 숨": "Enduring Breath of Gellenheim", "겔렌하임의 보석": "Gem of Gellenheim", "겔렌하임의 제례칼": "Ritual Knife of Gellenheim", "겨누어 쏘았다": "took aim and fired", "겨울을 넘긴 철퇴": "Winter-Surviving Mace", "격식 차리는 학술원 마도사가 직접 지은 거창한 주문 이름을 외치는 영웅담 광팬": "A formal academy Mage who loves heroic sagas and shouts the grand spell names she invents.", "격식을 지키는 손님. 서두르면 값을 올린다": "A guest who respects the formalities; rushing raises the price", "견습 인형": "Apprentice Automaton", "견습 인형 호출": "Call Apprentice Automaton", "결투를 이기고 난 몸으로": "Fresh from winning a duel", "겹깃이 있는 외투": "Coat with a layered collar", "겹방패 펜던트": "Pendant of Layered Shields", "겹친 강철 어깨판": "Layered steel shoulder plates", "겹친 두 활대": "Two overlapping bow staves", "겹친 방패": "Layered Shields", "경계도시": "Border Cities", "경보": "Alarm", "경보 수정구": "Alarm Orb", "경험치 +10%": "Experience +10%", "경험치 +{border.exp%}%(출전한 경계도시 사람마다).": "Experience +{border.exp%}% per active Border Cities party member.", "곁에 앉아 이야기를 나눈다": "Sit together and talk", "곁에서 쉬기": "Rest together", "계곡 공동체들이 맹약으로 묶인 연방. 용병을 내보내 먹고산다.": "A federation of valley communities bound by oath, making its living as mercenaries.", "계곡 맹약": "Valley Covenant", "계곡 맹약과 용병": "Valley pacts and mercenaries", "계급이나 호칭이 아닌 이름으로 불러 주어야 한다": "Call her by name, not rank or title", "계약 이행": "Fulfill Contract", "계약 조항": "Contract Clause", "계약 집행자": "Contract Enforcer", "계약서를 성경처럼 외우는 부대장인데 실은 유령과 언데드를 무서워한다": "A lieutenant who knows every contract by heart yet fears ghosts and undead.", "계약서처럼 정리된 규칙": "Rules written out like a contract", "계약은 끝났다": "Contract Fulfilled", "계약은 지킨다": "Keep the contract", "계약을 집행했다": "enforced the contract", "계약의 시대": "Age of Contracts", "계약이 끝난 사람을 일회용처럼 대하는 말과 태도": "Treating a former contractor as disposable", "계열 능력치": "Primary Attribute", "고갈 공명": "Exhaustion Resonance", "고갈 상태인 적에게 주는 피해 배율 ×2.5(다른 직업 ×1.5) — 고갈시키고 직접 가장 크게 터뜨린다": "Damage multiplier against depleted enemies ×2.5 (other classes ×1.5) — depletes enemies, then deals the greatest burst damage directly", "고갈된 적에게 주는 피해 ×2.5 → ×7.5, 혼돈 파동은 거기에 다시 ×1.5": "Damage to depleted enemies ×2.5 → ×7.5; Chaos Wave gains another ×1.5", "고갈된 적에게 주는 피해 ×2.5 → ×{1}, 혼돈 파동은 거기에 다시 ×{2}": "Damage to exhausted enemies ×2.5 → ×{1}; Chaos Wave gains another ×{2}", "고개에서 얼어 죽은 상단 사람들이 한데 뭉친 것": "Traders frozen to death on the pass, gathered into one body", "고개의 굶주린 것": "Starveling of the Pass", "고개의 망자": "Dead of the Pass", "고갯길을 건넌 구슬": "Pass-Crossing Orb", "고갯길을 건넌 망토": "Pass-Crossing Cloak", "고갯길을 건넌 문장": "Pass-Crossing Crest", "고갯길을 건넌 연금봉": "Pass-Crossing Alchemy Rod", "고갯길을 건넌 은목걸이": "Pass-Crossing Silver Necklace", "고갯길을 건넌 지팡이": "Pass-Crossing Staff", "고갯길을 건넌 펜던트": "Pass-Crossing Pendant", "고갯길을 넘은 철퇴": "Pass-Crossing Mace", "고급": "Uncommon", "고드프루아": "Godfroi", "고른 공명구": "Even Resonance Orb", "고립된 탐사대 구조": "Rescue the stranded expedition", "고립의 해 겨울에 칸의 선봉은 군을 물렸다. 보급이 끊겨서였을까, 아니면 제국 북변을 이미 다 살펴본 뒤였을까.": "In the winter of the Year of Isolation, the khan's vanguard withdrew. Had its supplies failed, or had it already learned enough of the empire's northern border?", "고립의 해, 변경 병사들은 북쪽과 심연 사이에서 눈을 돌릴 겨를이 없었다. 한 사람이 쓰러져도 성벽의 그 자리는 비울 수 없었다.": "In the Year of Isolation, the March's soldiers could scarcely turn their eyes from north to Abyss. Even when one fell, that place on the wall could not be left empty.", "고립의 해에 그라벤 변경 병사들은 북쪽과 심연 쪽을 번갈아 지켰다. 이 투구는 그 두 방향의 바람을 다 맞았다.": "In the Year of Isolation, Graben's border troops took turns watching north and toward the Abyss. This helm has weathered both winds.", "고마운 마음은 진짜예요. 그래도 오늘은 안 돼요. 수프는 같이 먹어요.": "I do appreciate it. Still, not tonight. Let's share some soup.", "고마워요. 천천히, 다리 때문에 자세는 내가 정할게요. ……이름 불러 줄래요? 그것만 해 주면 돼요.": "Thank you. Slowly, please. I'll choose our position because of my leg. ...Will you say my name? That's all I ask.", "고양이": "Cat", "고양이, 표범": "Cats, leopards", "고양이과": "Feline", "고용과 계약 관계를 이용해 압박하는 것": "Pressuring her through employment or a contract", "고운 건틀릿": "Fine Gauntlets", "고운 긴 외투": "Fine Long Coat", "고운 수정 반지": "Fine Crystal Ring", "고운 은목걸이": "Fine Silver Necklace", "고운 은팔찌": "Fine Silver Bracelet", "고운 짧은 망토": "Fine Short Cloak", "고통받는 사람이 곁에 있는 날에는 마음이 그쪽에 가 있다": "When someone nearby is suffering, her thoughts remain with them", "고함과 큰 소리": "Shouting and loud noise", "고향과 골목을 깎아내리는 말": "Insulting her hometown or the lane where she grew up", "곡괭이를 휘둘러 적 전체에 ×1.2의 피해를 준다(심연 −15씩). 대신 자하르의 방어가 1턴 동안 20% 줄어든다.": "Swing a pickaxe to deal ×1.2 damage to all enemies (Abyss −15 each). Zahar's Defense drops by 20% for 1 turn.", "곧은 곡검": "Straight Scimitar", "곧은 단궁": "Straight Shortbow", "곧은 양날과 긴 손잡이": "Straight double-edged blade and long grip", "곧은 장검": "Straight Longsword", "곧은 전투망치": "Straight Warhammer", "골든타임": "Golden Hour", "골목 끝집 국수를 먹고 난 뒤의 배부른 기분": "The full, contented feeling after noodles from the shop at the end of the lane", "골목 사람을 속이는 외지인 연기": "Pretending to be an outsider who cheats the people of her lane", "골목 인맥": "Street Connections", "곰팡내 나는 향을 피워 올리는 낡은 향로": "An old censer spilling incense that reeks of mold", "공격": "attack", "공격 +15%": "Attack +15%", "공격 약화": "attack penalty", "공격·방어 +15%": "Attack·Defense +15%", "공격마다 「출혈」 1중첩이 쌓인다(최대 3, 3턴, 중첩당 매 턴 민첩 ×0.2). 3중첩이 되면 즉시 터져서 남은 출혈 피해 전부에 ×(1+50%)를 곱해 한꺼번에 주고, 중첩은 0으로 돌아간다. 맞은 적은 다음 차례가 5% 늦어지며(폭발은 18%), 이 효과는 한 차례에 한 번만 걸린다.": "Each attack adds 1 stack of Bleed (maximum 3, 3 turns, Agility ×0.2 damage per stack each turn). At 3 stacks, Bleed bursts immediately, dealing all remaining Bleed damage at ×(1+50%) and resetting stacks to 0. The target's next turn is delayed by 5% (18% on burst); this effect applies only once per turn.", "공격받으면 15% 확률로 반격": "15% chance to counterattack when hit", "공격받으면 {kern.ch3%}% 확률로 반격하고, 패배 때 잃는 금화는 -{kern.lose2%}%. 패배해도 탐색 수확의 {kern.keep3%}%는 챙긴다": "{kern.ch3%}% counter chance when hit; gold lost on defeat −{kern.lose2%}%; keep {kern.keep3%}% of exploration loot even on defeat", "공격이 50% 확률로 한 번 더 시전된다(메아리, 피해 70%).": "50% chance for an attack to be cast again (Echo, 70% damage).", "공격이 최선의 방어": "Offense Is the Best Defense", "공격한 뒤 30% 확률로 곧바로 한 번 더 공격한다. 연속은 최대 2번까지다.": "After attacking, 30% chance to attack again immediately. Can chain up to 2 extra attacks.", "공격한 뒤 대상의 HP가 25% 이하면 그 자리에서 처형한다(구역 보스·층 끝 우두머리·균열 핵에게는 처형 대신 피해 +30%). 처형하면 행동 게이지가 50% 찬다.": "After an attack, execute the target if its HP is 25% or lower (against zone bosses, floor-end chiefs and rift cores, deal +30% damage instead of executing). An execution fills the action gauge by 50%.", "공격할 때 18% 확률로 1턴 동안 치명타 확률 +13%p": "On attack, 18% chance: Critical Hit Chance +13%p for 1 turns", "공격할 때 20% 확률로 1턴 동안 치명타 확률 +8%p": "On attack, 20% chance: Critical Hit Chance +8%p for 1 turns", "공격할 때 22% 확률로 1턴 동안 치명타 확률 +13%p": "On attack, 22% chance: Critical Hit Chance +13%p for 1 turns", "공격할 때 23% 확률로 2턴 동안 치명타 확률 +9%p": "On attack, 23% chance: Critical Hit Chance +9%p for 2 turns", "공격할 때 24% 확률로 1턴 동안 치명타 확률 +9%p": "On attack, 24% chance: Critical Hit Chance +9%p for 1 turns", "공격할 때 27% 확률로 2턴 동안 치명타 확률 +11%p": "On attack, 27% chance: Critical Hit Chance +11%p for 2 turns", "공격할 때 27% 확률로 2턴 동안 치명타 확률 +12%p": "On attack, 27% chance: Critical Hit Chance +12%p for 2 turns", "공격할 때 28% 확률로 1턴 동안 치명타 확률 +9%p": "On attack, 28% chance: Critical Hit Chance +9%p for 1 turns", "공격할 때 29% 확률로 2턴 동안 치명타 확률 +12%p": "On attack, 29% chance: Critical Hit Chance +12%p for 2 turns", "공격할 때 {p}% 확률로 {n}턴 동안 치명타 확률 +{x}%p": "On attack, {p}% chance to gain +{x}%p critical chance for {n} turns", "공명의 검은 고리": "Black Ring of Resonance", "공성 돌격": "Siege Charge", "공성 병기": "Siege Engines", "공성탑의 잔해": "Siege Tower Wreck", "공인 마법사": "Licensed Mage", "공통": "Common", "공허 흡수": "Void Absorption", "공허 흡수 목걸이": "Void-Drinking Necklace", "공화국에 고용됐다가 눌러앉은 케른 용병": "A Kern mercenary who took a contract with the Republic and never left.", "과열": "Overheat", "관 뚜껑": "Coffin Lid", "관객 앞에서는 큰소리치는 쇼맨인데 무대 밖에서는 낯가림에 말을 더듬는 검투사": "A swaggering Gladiator before a crowd who stammers with strangers offstage.", "관객이 없으니까 말이 더 안 나와요. 그래도 이 말만은 해야겠어요. 오늘은 거절이에요.": "Without an audience, words are harder. But I have to say this: no, not tonight.", "관통 사격": "Piercing Shot", "관통 사격을 날렸다": "fired a piercing shot", "광기": "Frenzy", "광낸 가죽 장갑": "Polished Leather Gloves", "광낸 검투검": "Polished Gladiator's Blade", "광낸 목걸이": "Polished Necklace", "광낸 별무늬 반지": "Polished Star-Marked Ring", "광낸 성표": "Polished Holy Emblem", "광낸 암살검": "Polished Assassin's Blade", "광선": "Beam", "광선을 쏘았다": "fired a beam", "괜찮아요, 정말로요. 그럼 오늘은 평소처럼 차 한 잔 드시고 가세요. 장부에는 아무것도 적지 않을게요.": "It's all right, truly. Have a cup of tea like you usually do. Nothing will go in the ledger.", "괜찮아요. 오늘은 그냥 곁에 있어 줘요. 살아서 왔잖아요. 그럼 됐어요.": "It's all right. Just stay beside me for a while. You came back alive. That's enough.", "교단을 모독하는 말": "Blasphemy against the church", "교역 공터": "Trading Clearing", "구년 전쟁 소식이 발로아 항구에 닿자 말이 두 갈래로 갈렸다. 흑요 방벽은 신관이 풀어 버린 걸까, 범람에 터진 걸까.": "When news of the Nine Years' War reached Valois harbor, two stories arrived with it. Had the priests lowered the obsidian ward, or had the flood broken through?", "구두 약속을 뒤집거나 합의를 바꾸는 것": "Breaking a verbal promise or changing the agreement", "구름무늬 공명구": "Cloud-Marked Resonance Orb", "구름무늬 방패 갑옷": "Cloud-Marked Shield Armor", "구름무늬 사냥활": "Cloud-Marked Hunting Bow", "구름무늬 은목걸이": "Cloud-Marked Silver Necklace", "구름무늬 철퇴": "Cloud-Marked Mace", "구리 공허봉": "Copper Void Rod", "구리 수정봉": "Copper Crystal Rod", "구리 장식 암살검": "Copper Trimmed Assassin's Blade", "구리 장식 전투도끼": "Copper Trimmed Battleaxe", "구리 장식 전투망치": "Copper Trimmed Warhammer", "구리테 균열봉": "Copper-Rimmed Rift Rod", "구리테 기도홀": "Copper-Rimmed Prayer Scepter", "구리테 룬 지팡이": "Copper-Rimmed Rune Staff", "구리테 증류봉": "Copper-Rimmed Distillation Rod", "구리테 지팡이": "Copper-Rimmed Staff", "구석 자리와 따뜻한 차 한 잔": "A corner seat and a cup of warm tea", "구역 보스": "Zone Boss", "국 한 그릇 나눠 먹은 뒤의 느긋한 분위기": "The easy mood after sharing a bowl of soup", "국부터 먹고, 웃으며 주도권을 주고받는 느긋한 밤": "Soup first, then a leisurely game of giving and taking control", "국부터 먹이고 웃기며 시작한다. 주도권을 번갈아 주고받는 장난을 즐기고, 신앙과 교리를 놀리는 말만은 받아 주지 않는다.": "She starts with soup and laughter. She enjoys trading control back and forth, but will not tolerate mockery of her faith or doctrine.", "국왕과 주신 교단이 권력을 나눠 쥔다. 이단 심문소가 마법을 감시한다.": "The king shares power with the High God's church. The Inquisition watches over magic.", "군복과 갑옷을 하나씩 천천히 푸는 순서": "Unfastening uniform and armor slowly, piece by piece", "군힐트": "Gunhild", "군힐트 폰 할렌": "Gunhild von Halen", "굳건한 방어": "Stalwart Defense", "굵은 금빛 고리": "Thick golden band", "굶주린 속삭임": "Starved Whisper", "굶주린 칼": "Hungry Blade", "굶주림의 핏빛 보석": "Bloodred Gem of Hunger", "굽은 갈고리 날": "Curved hook blade", "궁수": "Archer", "귀족 자제": "Noble Scion", "귀환 두루마리": "Return scroll", "귀환의 문": "Gate of Return", "규모의 경제": "Economies of Scale", "규정을 어긴 쪽에 손바닥 정도의 가벼운 「벌」을 주는 놀이(합의한 선에서)": "A light, consensual “punishment” on the palm for breaking a rule", "규칙과 신호를 먼저 정하고 시작하는 합의. 신호는 그녀가 정한다": "Setting rules and signals before beginning; she chooses the signal", "규칙과 신호를 먼저 정해야 한다. 뿔을 허락 없이 만지면 문이 닫히고, 떠나온 나라 이야기도 꺼내면 안 된다.": "Rules and signals come first. Touch her horns without asking and she withdraws; do not bring up the country she fled.", "규칙과 신호를 정하고 애태우는 조용한 밤": "A hushed night of rules, signals, and delicious suspense", "균열": "Rift", "균열 안쪽에 자리 잡은 핵을 부순다.": "Destroy the core deep inside the rift.", "균열 핵": "Rift Core", "균열 핵 토벌": "Destroy the rift core", "균형 잡힌 대검": "Balanced Greatsword", "균형 좋은 석궁": "Balanced Crossbow", "그 동료도 휴식 파티에 있다(예: with:urda)": "That companion is also in the resting party (for example, with:urda)", "그라벤": "Graben", "그라벤 요새": "Graben Fortress", "그라벤 조사단이 프리엔 화재 현장을 살피고 들고 나온 수정봉이다. 보고서는 진작 끝났는데 그을음만 오래 남았다.": "Graben's investigators carried this rod away from the Prien fire. The report was finished long ago; the soot was slower to leave.", "그라벤의 굳센 투지": "Steadfast Resolve of Graben", "그라벤의 남은 걸음": "Final Steps of Graben", "그라벤의 뒤늦은 불길": "Lingering Flame of Graben", "그라벤의 수정봉": "Crystal Rod of Graben", "그라벤의 장화": "Boots of Graben", "그라벤의 투구": "Helm of Graben", "그래요, 괜찮아요. 그냥 해 본 말이에요. 국이나 한 그릇 먹고 가요. 오늘은 그걸로 됐어요.": "That's fine. I was only asking. Stay for a bowl of soup, at least. That will be enough tonight.", "그래요. 천천히 해요, 급할 것 없어요. 불은 내가 낮출게요. ……이쪽으로 와요.": "Yes. Slowly. There's no hurry. I'll dim the light. ...Come here.", "그림자 궁수": "Shadow Archer", "그림자 연타": "Shadow Flurry", "그림자 화살": "Shadow arrow", "그림자 화살을 날렸다": "loosed a shadow arrow", "그림자로 짠 실로 적 1명의 발목을 감아 다음 차례를 40% 뒤로 미룬다(심연 −3).": "Shadow-woven thread binds 1 enemy's ankle, delaying its next turn by 40% (Abyss −3).", "그물 던지기": "Cast Net", "그물 던지는 어부": "Net-Casting Fisherman", "그물과 작살을 든 어부 망령": "A fisherman's ghost armed with net and harpoon", "그을린 나무 지팡이": "Scorched wood